// ==UserScript==
// @name         數據庫-可定製副本
// @namespace    http://tampermonkey.net/
// @version      1.1
// @description  爲不同的角色卡提供獨立的、使用不同默認模板的數據庫。通過修改 @name 和 UNIQUE_SCRIPT_ID 來創建互不干擾的副本。
// @author       Cline (AI Assisted)
// @match        */*
// @grant        none
// @註釋掉的require  https://code.jquery.com/jquery-3.7.1.min.js
// @註釋掉的require  https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.js
// ==/UserScript==

(function () {
  'use strict';
  console.log('ACU_SCRIPT_DEBUG: AutoCardUpdater script execution started.'); // Very first log

  // --- 安全存儲 & 頂層窗口 ---
  const topLevelWindow_ACU = (typeof window.parent !== 'undefined' ? window.parent : window);

  // --- 存儲策略 ---
  // - 主存：寫入 SillyTavern 服務端設置（extensionSettings + saveSettings），同一酒館服務端下所有瀏覽器一致。
  // - 本地副本：同時寫入 IndexedDB（僅本瀏覽器可用，用作酒館設置讀取失敗時的回退）。
  // - 讀取順序：酒館設置 -> IndexedDB -> 默認設置。
  // - 禁止 localStorage / sessionStorage（除非手動關閉禁用開關）。
  const FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU = true;
  const ALLOW_LEGACY_LOCALSTORAGE_MIGRATION_ACU = false; // 如需把舊 localStorage 設置遷移到酒館設置，可改爲 true（遷移後仍不再寫 localStorage）

  // legacyLocalStorage_ACU：僅用於“可選遷移”，不是配置持久化後端
  let legacyLocalStorage_ACU = null;
  try { legacyLocalStorage_ACU = topLevelWindow_ACU.localStorage; } catch (e) { legacyLocalStorage_ACU = null; }

  // storage_ACU：舊代碼裏大量把它當作“配置存儲”。現在默認是一個 NO-OP 存儲，避免任何本地持久化。
  // 真實持久化後端請走 getConfigStorage_ACU()（優先寫入酒館設置）。
  let storage_ACU = {
      getItem: () => null,
      setItem: () => {},
      removeItem: () => {}
  };

  if (!FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU) {
      try {
          storage_ACU = topLevelWindow_ACU.localStorage;
      } catch (e) {
          console.error('[AutoCardUpdater] localStorage is not available. Settings will not be saved.', e);
          storage_ACU = { getItem: () => null, setItem: () => {}, removeItem: () => {} };
      }
  }

  // --- 腳本配置常量 ---
  const DEBUG_MODE_ACU = true; // Keep this true for now for user debugging

  // --- [核心改造] 唯一標識符 ---
  // !!! 重要: 如果您想創建此腳本的獨立副本（例如，爲不同角色使用不同模板），
  // !!! 請將下面的 'biaozhunbanv2_v1' 更改爲一個【全新的、唯一的】英文名稱。
  // !!! 例如: 'my_sci_fi_db', 'fantasy_world_db' 等。
  // !!! 同時，請務必修改上面的 @name 以便在菜單中區分它們。
  const UNIQUE_SCRIPT_ID = 'shujuku_v120'; // <--- 爲每個副本修改這裏
  const SCRIPT_ID_PREFIX_ACU = UNIQUE_SCRIPT_ID;

  const POPUP_ID_ACU = `${SCRIPT_ID_PREFIX_ACU}-popup`;
  const MENU_ITEM_ID_ACU = `${SCRIPT_ID_PREFIX_ACU}-menu-item`;

  // ═══════════════════════════════════════════════════════════════════════════════
  // ███ 獨立窗口系統 - 不依賴酒館 callGenericPopup ███
  // ═══════════════════════════════════════════════════════════════════════════════

  // 窗口管理器：追蹤所有打開的窗口實例
  const ACU_WindowManager = {
    windows: new Map(), // id -> { $el, zIndex, ... }
    baseZIndex: 10000,
    topZIndex: 10000,

    register(id, $el) {
      this.topZIndex++;
      this.windows.set(id, { $el, zIndex: this.topZIndex });
      $el.css('z-index', this.topZIndex);
    },

    unregister(id) {
      this.windows.delete(id);
    },

    bringToFront(id) {
      const win = this.windows.get(id);
      if (!win) return;
      this.topZIndex++;
      win.zIndex = this.topZIndex;
      win.$el.css('z-index', this.topZIndex);
    },

    getWindow(id) {
      return this.windows.get(id)?.$el || null;
    },

    isOpen(id) {
      return this.windows.has(id);
    },

    closeAll() {
      this.windows.forEach((_, id) => {
        const $el = this.windows.get(id)?.$el;
        if ($el) $el.remove();
      });
      this.windows.clear();
    }
  };

  // 獨立窗口樣式（只注入一次）
  const ACU_WINDOW_STYLES_INJECTED_FLAG = `${SCRIPT_ID_PREFIX_ACU}_window_styles_injected`;
  const ACU_UI_THEME_STORAGE_KEY = `${SCRIPT_ID_PREFIX_ACU}_ui_theme_v1`;

  function getACUTheme_ACU() {
    try {
      const store = getConfigStorage_ACU();
      const savedTheme = String(store?.getItem?.(ACU_UI_THEME_STORAGE_KEY) || '').trim().toLowerCase();
      return savedTheme === 'silk' ? 'silk' : 'ink';
    } catch (e) {
      return 'ink';
    }
  }

  function setACUTheme_ACU(theme) {
    const normalizedTheme = theme === 'silk' ? 'silk' : 'ink';
    try {
      const store = getConfigStorage_ACU();
      store?.setItem?.(ACU_UI_THEME_STORAGE_KEY, normalizedTheme);
    } catch (e) {
      console.warn('[ACU] Failed to persist UI theme:', e);
    }
    return normalizedTheme;
  }

  function applyACUThemeToDocument_ACU(targetDoc, theme = null) {
    const doc = targetDoc || (topLevelWindow_ACU?.document || document);
    const activeTheme = theme === 'silk' || theme === 'ink' ? theme : getACUTheme_ACU();
    const body = doc?.body;
    if (!body || !body.classList) return activeTheme;
    body.classList.toggle('acu-theme-silk', activeTheme === 'silk');
    body.setAttribute('data-acu-theme', activeTheme);
    return activeTheme;
  }

  function syncACUThemeButtons_ACU(targetDoc) {
    const doc = targetDoc || (topLevelWindow_ACU?.document || document);
    const activeTheme = applyACUThemeToDocument_ACU(doc);
    const nextThemeLabel = activeTheme === 'silk' ? '墨紙' : '素紗';
    const nextThemeTitle = activeTheme === 'silk' ? '切換爲墨紙主題' : '切換爲素紗主題';
    try {
      doc.querySelectorAll('.acu-window-btn.theme-toggle .acu-theme-toggle-text').forEach((el) => {
        el.textContent = nextThemeLabel;
      });
      doc.querySelectorAll('.acu-window-btn.theme-toggle').forEach((el) => {
        el.setAttribute('title', nextThemeTitle);
      });
    } catch (e) {
      console.warn('[ACU] Failed to sync theme buttons:', e);
    }
    return activeTheme;
  }

  function toggleACUTheme_ACU(targetDoc) {
    const nextTheme = getACUTheme_ACU() === 'silk' ? 'ink' : 'silk';
    setACUTheme_ACU(nextTheme);
    applyACUThemeToDocument_ACU(targetDoc, nextTheme);
    syncACUThemeButtons_ACU(targetDoc);
    return nextTheme;
  }

  function injectACUWindowStyles() {
    // 始終往酒館主窗口注入樣式
    const targetWin = topLevelWindow_ACU || window;
    const targetDoc = targetWin.document;

    if (targetWin[ACU_WINDOW_STYLES_INJECTED_FLAG]) return;
    targetWin[ACU_WINDOW_STYLES_INJECTED_FLAG] = true;

    const css = `
      /* ═══════════════════════════════════════════════════════════════
         星·數據庫 獨立窗口系統
         古卷雙主題：墨色 / 素紗
         ═══════════════════════════════════════════════════════════════ */

      .acu-window-overlay {
        position: fixed;
        top: 0; left: 0; right: 0; bottom: 0;
        background: rgba(17, 15, 13, 0.56);
        backdrop-filter: blur(3px);
        -webkit-backdrop-filter: blur(3px);
        z-index: 9999;
        animation: acuOverlayFadeIn 0.24s ease-out;
      }
      body.acu-theme-silk .acu-window-overlay {
        background: rgba(94, 84, 69, 0.16);
      }
      @keyframes acuOverlayFadeIn {
        from { opacity: 0; }
        to { opacity: 1; }
      }

      .acu-window {
        --acu-panel-bg: #0b0f15;
        --acu-panel-border: #1f2937;
        --acu-panel-text: #c1b9ad;
        --acu-panel-text-dim: #9e978e;
        --acu-panel-text-mute: #645e55;
        --acu-panel-accent: #7bb7ff;
        --acu-panel-hover: #101826;
        position: fixed;
        display: flex;
        flex-direction: column;
        background-color: var(--acu-panel-bg);
        background-image:
          url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E"),
          linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent 30%);
        border: 1px solid var(--acu-panel-border);
        border-radius: 2px;
        box-shadow: 0 24px 60px rgba(0, 0, 0, 0.42);
        overflow: hidden;
        min-width: 400px;
        min-height: 300px;
        animation: acuWindowSlideIn 0.25s ease-out;
        color-scheme: dark;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        font-weight: 500;
        color: var(--acu-panel-text);
        text-rendering: optimizeLegibility;
        -webkit-font-smoothing: antialiased;
      }
      body.acu-theme-silk .acu-window {
        --acu-panel-bg: #f4f1eb;
        --acu-panel-border: #e0dacb;
        --acu-panel-text: #4a453f;
        --acu-panel-text-dim: #6e675e;
        --acu-panel-text-mute: #9e978e;
        --acu-panel-accent: #8a6b5e;
        --acu-panel-hover: #ebe7de;
        color-scheme: light;
        box-shadow: 0 18px 42px rgba(72, 59, 43, 0.16);
      }
      @keyframes acuWindowSlideIn {
        from { opacity: 0; transform: scale(0.97) translateY(-14px); }
        to { opacity: 1; transform: scale(1) translateY(0); }
      }

      .acu-window.maximized {
        top: 10px !important;
        left: 10px !important;
        width: calc(100vw - 20px) !important;
        height: calc(100vh - 20px) !important;
        border-radius: 12px;
      }

      /* 窄屏模式下全屏時減小邊距，確保頭部完全可見 */
      @media screen and (max-width: 1100px) {
        .acu-window.maximized {
          top: 5px !important;
          left: 5px !important;
          width: calc(100vw - 10px) !important;
          height: calc(100vh - 10px) !important;
          border-radius: 8px;
        }
        .acu-window-header {
          padding: 10px 12px;
        }
        .acu-window-controls {
          gap: 6px;
          margin-right: 0; /* 窄屏模式下關閉按鈕靠右 */
        }
        .acu-window-btn {
          width: 32px;
          height: 32px;
        }
        .acu-window {
          min-width: 320px; /* 窄屏下允許更小的最小寬度 */
        }
      }

      /* 超窄屏模式下全屏時進一步優化 */
      @media screen and (max-width: 768px) {
        .acu-window {
          min-width: min(320px, calc(100vw - 12px)) !important; /* 手機端保留邊距，避免遮擋底層界面 */
          min-height: min(360px, calc(100dvh - 12px)) !important;
          max-width: calc(100vw - 12px) !important;
          max-height: calc(100vh - 12px) !important;
          max-height: calc(100dvh - 12px) !important; /* 使用動態視口高度，避免移動瀏覽器地址欄問題 */
        }
        .acu-window.maximized {
          top: 6px !important;
          left: 6px !important;
          width: calc(100vw - 12px) !important;
          height: calc(100vh - 12px) !important;
          height: calc(100dvh - 12px) !important; /* 優先使用動態視口高度 */
          max-width: calc(100vw - 12px) !important;
          max-height: calc(100vh - 12px) !important;
          max-height: calc(100dvh - 12px) !important;
          border-radius: 10px;
          border: 1px solid var(--acu-panel-border);
        }
        .acu-window-header {
          padding: 8px 10px;
          min-height: 44px; /* 確保頭部高度足夠 */
          flex-shrink: 0;
        }
        .acu-window-controls {
          margin-right: 0; /* 超窄屏模式下關閉按鈕靠右 */
        }
        .acu-window-title {
          font-size: 13px;
        }
        .acu-window-btn {
          width: 36px;
          height: 36px;
          font-size: 16px;
        }
        .acu-window-body {
          max-width: 100vw;
          overflow-x: hidden;
          overflow-y: auto;
          /* 確保body能正確滾動，使用flex佈局撐滿剩餘空間 */
          flex: 1 1 0;
          min-height: 0; /* 關鍵：允許flex子元素收縮 */
        }
      }

      /* 極窄屏模式（≤480px）進一步壓縮 */
      @media screen and (max-width: 480px) {
        .acu-window-header {
          padding: 6px 8px;
          min-height: 40px;
        }
        .acu-window-title {
          font-size: 12px;
          gap: 6px;
        }
        .acu-window-title i {
          font-size: 14px;
        }
        .acu-window-btn {
          width: 32px;
          height: 32px;
          font-size: 14px;
        }
        .acu-window-controls {
          gap: 4px;
          margin-right: 0; /* 極窄屏模式下關閉按鈕靠右 */
        }
      }

      /* 超小屏模式（≤360px）最小化頭部佔用 */
      @media screen and (max-width: 360px) {
        .acu-window-header {
          padding: 4px 6px;
          min-height: 36px;
        }
        .acu-window-title {
          font-size: 11px;
          gap: 4px;
        }
        .acu-window-title i {
          font-size: 12px;
        }
        .acu-window-btn {
          width: 28px;
          height: 28px;
          font-size: 12px;
          border-radius: 6px;
        }
        .acu-window-controls {
          margin-right: 0; /* 超小屏模式下關閉按鈕靠右 */
        }
      }

      .acu-window-header {
        display: flex;
        align-items: center;
        justify-content: space-between;
        padding: 12px 16px;
        background: transparent;
        border-bottom: 1px solid var(--acu-panel-border);
        cursor: move;
        user-select: none;
        flex-shrink: 0;
      }

      .acu-window-title {
        font-size: 14px;
        font-weight: 600;
        letter-spacing: 1px;
        color: var(--acu-panel-text);
        display: flex;
        align-items: center;
        gap: 10px;
        flex: 1;
        min-width: 0;
        overflow: hidden;
      }
      .acu-window-title i {
        color: var(--acu-panel-accent);
        flex-shrink: 0;
      }
      .acu-window-title span {
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
      }

      .acu-window-controls {
        display: flex;
        gap: 6px;
        flex-shrink: 0;
        margin-left: 8px;
      }

      .acu-window-btn {
        width: 30px;
        height: 30px;
        border: 1px solid transparent;
        border-radius: 1px;
        background: transparent;
        color: var(--acu-panel-text-mute);
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.18s ease;
        font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      }
      .acu-window-btn:hover {
        background: var(--acu-panel-hover);
        border-color: var(--acu-panel-border);
        color: var(--acu-panel-text);
      }
      .acu-window-btn.maximize:hover {
        color: var(--acu-panel-accent);
      }
      .acu-window-btn.close:hover {
        background: rgba(123, 183, 255, 0.10);
        border-color: var(--acu-panel-accent);
        color: var(--acu-panel-accent);
      }
      .acu-window-btn.theme-toggle {
        width: auto;
        min-width: 58px;
        padding: 0 10px;
        font-size: 11px;
        letter-spacing: 1px;
      }
      .acu-theme-toggle-text {
        display: inline-block;
        line-height: 1;
        transform: translateY(-0.5px);
      }

      .acu-window-body {
        flex: 1 1 0;
        min-height: 0; /* 關鍵：允許flex子元素收縮到小於內容高度 */
        overflow: auto;
        overflow-x: hidden;
        padding: 0;
        /* 確保內容不會撐破容器 */
        display: flex;
        flex-direction: column;
      }

      /* 窗口body內的內容容器 */
      .acu-window-body > * {
        flex: 1 1 0;
        min-height: 0;
        overflow-y: auto;
        box-sizing: border-box;
      }

      /* 窗口大小調整手柄 */
      .acu-window-resize-handle {
        position: absolute;
        background: transparent;
      }
      .acu-window-resize-handle.se {
        right: 0; bottom: 0;
        width: 20px; height: 20px;
        cursor: se-resize;
      }
      .acu-window-resize-handle.se::after {
        content: '';
        position: absolute;
        right: 4px; bottom: 4px;
        width: 10px; height: 10px;
        border-right: 2px solid var(--acu-panel-border);
        border-bottom: 2px solid var(--acu-panel-border);
        opacity: 0.72;
      }
      .acu-window-resize-handle.e {
        right: 0; top: 40px; bottom: 20px;
        width: 6px;
        cursor: e-resize;
      }
      .acu-window-resize-handle.s {
        left: 20px; right: 20px; bottom: 0;
        height: 6px;
        cursor: s-resize;
      }
      .acu-window-resize-handle.w {
        left: 0; top: 40px; bottom: 20px;
        width: 6px;
        cursor: w-resize;
      }
      .acu-window-resize-handle.n {
        left: 20px; right: 20px; top: 0;
        height: 6px;
        cursor: n-resize;
      }
      .acu-window-resize-handle.nw {
        left: 0; top: 0;
        width: 20px; height: 20px;
        cursor: nw-resize;
      }
      .acu-window-resize-handle.ne {
        right: 0; top: 0;
        width: 20px; height: 20px;
        cursor: ne-resize;
      }
      .acu-window-resize-handle.sw {
        left: 0; bottom: 0;
        width: 20px; height: 20px;
        cursor: sw-resize;
      }
    `;

    const style = targetDoc.createElement('style');
    style.id = `${SCRIPT_ID_PREFIX_ACU}-window-styles`;
    style.textContent = css;
    (targetDoc.head || targetDoc.documentElement).appendChild(style);
  }

  // ═══ 窗口狀態存儲鍵 ═══
  const ACU_WINDOW_STATE_STORAGE_KEY = `${SCRIPT_ID_PREFIX_ACU}_windowStates`;

  /**
   * 獲取窗口狀態存儲對象
   */
  function getWindowStates_ACU() {
    try {
      const store = getConfigStorage_ACU();
      const raw = store?.getItem?.(ACU_WINDOW_STATE_STORAGE_KEY);
      if (raw) {
        const parsed = safeJsonParse_ACU(raw, {});
        return (typeof parsed === 'object' && parsed !== null) ? parsed : {};
      }
    } catch (e) {
      console.warn('[ACU] Failed to read window states:', e);
    }
    return {};
  }

  /**
   * 保存窗口狀態
   * @param {string} windowId - 窗口ID
   * @param {object} state - 窗口狀態 { width, height, isMaximized }
   */
  function saveWindowState_ACU(windowId, state) {
    try {
      const states = getWindowStates_ACU();
      states[windowId] = state;
      const store = getConfigStorage_ACU();
      store?.setItem?.(ACU_WINDOW_STATE_STORAGE_KEY, safeJsonStringify_ACU(states, '{}'));
      // 觸發酒館設置持久化
      persistTavernSettings_ACU();
    } catch (e) {
      console.warn('[ACU] Failed to save window state:', e);
    }
  }

  /**
   * 獲取指定窗口的狀態
   * @param {string} windowId - 窗口ID
   * @returns {object|null} 窗口狀態或null
   */
  function getWindowState_ACU(windowId) {
    const states = getWindowStates_ACU();
    return states[windowId] || null;
  }

  /**
   * 創建獨立浮動窗口
   * @param {object} options
   * @param {string} options.id - 窗口唯一ID
   * @param {string} options.title - 窗口標題
   * @param {string} options.content - 窗口內容HTML
   * @param {number} [options.width=900] - 初始寬度
   * @param {number} [options.height=700] - 初始高度
   * @param {boolean} [options.modal=false] - 是否爲模態窗口（帶遮罩）
   * @param {boolean} [options.resizable=true] - 是否可調整大小
   * @param {boolean} [options.maximizable=true] - 是否可最大化
   * @param {boolean} [options.startMaximized=false] - 是否啓動時全屏
   * @param {boolean} [options.rememberState=true] - 是否記住窗口狀態
   * @param {function} [options.onClose] - 關閉回調
   * @param {function} [options.onReady] - 窗口就緒回調（DOM已插入）
   * @returns {jQuery} 窗口jQuery對象
   */
  function createACUWindow(options) {
    const {
      id,
      title = '窗口',
      content = '',
      width = 900,
      height = 700,
      modal = false,
      resizable = true,
      maximizable = true,
      startMaximized = false,
      rememberState = true, // 默認記住窗口狀態
      onClose,
      onReady
    } = options;

    // 確保樣式已注入
    injectACUWindowStyles();

    // 如果窗口已存在，直接顯示並置頂
    if (ACU_WindowManager.isOpen(id)) {
      ACU_WindowManager.bringToFront(id);
      return ACU_WindowManager.getWindow(id);
    }

    // ═══ 關鍵：始終掛載到酒館主窗口（topLevelWindow_ACU）═══
    const targetWin = topLevelWindow_ACU || window;
    const targetDoc = targetWin.document;
    const $ = targetWin.jQuery || (typeof jQuery_API_ACU !== 'undefined' ? jQuery_API_ACU : null);
    if (!$) {
      console.error('[ACU] jQuery not available for window creation');
      return null;
    }

    // 計算初始位置（居中）—— 使用主窗口的尺寸
    const viewW = targetWin.innerWidth || 1200;
    const viewH = targetWin.innerHeight || 800;

    // ═══ 窄屏檢測：≤1100px 視爲窄屏，≤768px 視爲手機屏 ═══
    const isNarrowScreen = viewW <= 1100;
    const isPhoneScreen = viewW <= 768;

    // ═══ 恢復上次保存的窗口狀態 ═══
    let savedState = null;
    let useSavedState = false;
    if (rememberState) {
      savedState = getWindowState_ACU(id);
      // 只有在非窄屏模式下才使用保存的狀態，窄屏始終使用響應式尺寸
      if (savedState && !isNarrowScreen) {
        useSavedState = true;
      }
    }

    // 確保寬高不超過視口；手機端使用更緊湊的浮層尺寸，避免遮擋過多聊天內容
    let initialW, initialH;
    if (useSavedState && savedState.width && savedState.height) {
      // 使用保存的窗口尺寸（確保不超過當前視口）
      initialW = Math.max(400, Math.min(savedState.width, viewW - 40));
      initialH = Math.max(300, Math.min(savedState.height, viewH - 40));
    } else if (isPhoneScreen) {
      const phoneHorizontalMargin = 12;
      const phoneVerticalMargin = 12;
      const phoneMinWidth = Math.min(320, Math.max(280, viewW - phoneHorizontalMargin));
      const phoneMinHeight = Math.min(360, Math.max(280, viewH - phoneVerticalMargin));
      initialW = Math.max(phoneMinWidth, Math.min(460, viewW - phoneHorizontalMargin));
      initialH = Math.max(phoneMinHeight, Math.min(Math.round(viewH * 0.82), viewH - phoneVerticalMargin));
    } else {
      initialW = Math.max(400, Math.min(width, viewW - 40));
      initialH = Math.max(300, Math.min(height, viewH - 40));
    }
    // 居中並確保不跑出屏幕
    const screenEdgePadding = isPhoneScreen ? 6 : 20;
    const initialX = Math.max(screenEdgePadding, Math.min((viewW - initialW) / 2, viewW - initialW - screenEdgePadding));
    const initialY = Math.max(screenEdgePadding, Math.min((viewH - initialH) / 2, viewH - initialH - screenEdgePadding));

    // 構建窗口HTML
    // ═══ 窄屏模式下不顯示全屏按鈕，只顯示關閉按鈕 ═══
    const showMaximizeBtn = maximizable && !isNarrowScreen;
    const windowHtml = `
      <div class="acu-window" id="${id}" style="left:${initialX}px; top:${initialY}px; width:${initialW}px; height:${initialH}px;">
        <div class="acu-window-header">
          <div class="acu-window-title">
            <i class="fa-solid fa-database"></i>
            <span>${title}</span>
          </div>
          <div class="acu-window-controls">
            <button class="acu-window-btn theme-toggle" title="切換主題"><span class="acu-theme-toggle-text">素紗</span></button>
            ${showMaximizeBtn ? '<button class="acu-window-btn maximize" title="最大化/還原"><i class="fa-solid fa-expand"></i></button>' : ''}
            <button class="acu-window-btn close" title="關閉"><i class="fa-solid fa-times"></i></button>
          </div>
        </div>
        <div class="acu-window-body">${content}</div>
        ${resizable ? `
          <div class="acu-window-resize-handle se"></div>
          <div class="acu-window-resize-handle e"></div>
          <div class="acu-window-resize-handle s"></div>
          <div class="acu-window-resize-handle w"></div>
          <div class="acu-window-resize-handle n"></div>
          <div class="acu-window-resize-handle nw"></div>
          <div class="acu-window-resize-handle ne"></div>
          <div class="acu-window-resize-handle sw"></div>
        ` : ''}
      </div>
    `;

    // 創建遮罩層（模態窗口）—— 掛載到主窗口 body
    let $overlay = null;
    if (modal) {
      $overlay = $(`<div class="acu-window-overlay" data-for="${id}"></div>`);
      $(targetDoc.body).append($overlay);
    }

    // 插入窗口 —— 掛載到主窗口 body
    const $window = $(windowHtml);
    $(targetDoc.body).append($window);
    applyACUThemeToDocument_ACU(targetDoc);
    syncACUThemeButtons_ACU(targetDoc);

    // 註冊到窗口管理器
    ACU_WindowManager.register(id, $window);

    // 點擊窗口置頂
    $window.on('mousedown', () => ACU_WindowManager.bringToFront(id));

    // 主題切換
    $window.find('.acu-window-btn.theme-toggle').on('click', (e) => {
      e.preventDefault();
      e.stopPropagation();
      toggleACUTheme_ACU(targetDoc);
    });

    // 關閉按鈕
    $window.find('.acu-window-btn.close').on('click', () => {
      // ═══ 關閉時保存窗口狀態 ═══
      if (rememberState && maximizable) {
        const currentState = {
          width: isMaximized ? restoreState.width : $window.width(),
          height: isMaximized ? restoreState.height : $window.height(),
          isMaximized: isMaximized
        };
        saveWindowState_ACU(id, currentState);
      }

      if (onClose) onClose();
      if ($overlay) $overlay.remove();
      $window.remove();
      ACU_WindowManager.unregister(id);
      // 清理事件
      $(targetDoc).off('.acuWindowDrag' + id);
      $(targetDoc).off('.acuWindowResize' + id);
    });

    // 遮罩層點擊關閉（可選）
    if ($overlay) {
      $overlay.on('click', (e) => {
        if (e.target === $overlay[0]) {
          // 可以選擇不關閉，或者關閉
          // 這裏選擇不關閉，用戶必須點擊關閉按鈕
        }
      });
    }

    // 最大化/還原
    let isMaximized = false;
    let restoreState = { left: initialX, top: initialY, width: initialW, height: initialH };

    const doMaximize = () => {
      restoreState = {
        left: parseInt($window.css('left')),
        top: parseInt($window.css('top')),
        width: $window.width(),
        height: $window.height()
      };
      $window.addClass('maximized');
      $window.find('.acu-window-btn.maximize i').removeClass('fa-expand').addClass('fa-compress');
      isMaximized = true;
    };

    const doRestore = () => {
      $window.removeClass('maximized');
      $window.css({
        left: restoreState.left + 'px',
        top: restoreState.top + 'px',
        width: restoreState.width + 'px',
        height: restoreState.height + 'px'
      });
      $window.find('.acu-window-btn.maximize i').removeClass('fa-compress').addClass('fa-expand');
      isMaximized = false;
    };

    $window.find('.acu-window-btn.maximize').on('click', () => {
      if (isMaximized) {
        doRestore();
      } else {
        doMaximize();
      }
    });

    // ═══ 啓動時全屏邏輯（優先級：窄屏強制全屏 > 保存的狀態 > startMaximized參數）═══
    // 平板窄屏默認全屏；手機模式保留邊距式浮層，避免遮擋過多內容
    if (isNarrowScreen && !isPhoneScreen && maximizable) {
      doMaximize();
    } else if (useSavedState && savedState.isMaximized && maximizable) {
      // 恢復上次的全屏狀態
      doMaximize();
    } else if (startMaximized && maximizable) {
      // 使用傳入的 startMaximized 參數
      doMaximize();
    }

    // 拖拽移動 —— 事件綁定到主窗口 document
    let isDragging = false;
    let dragStartX, dragStartY, windowStartX, windowStartY;

    $window.find('.acu-window-header').on('mousedown', (e) => {
      if ($(e.target).closest('.acu-window-controls').length) return;
      if (isMaximized) return;

      isDragging = true;
      dragStartX = e.clientX;
      dragStartY = e.clientY;
      windowStartX = parseInt($window.css('left'));
      windowStartY = parseInt($window.css('top'));

      $(targetDoc.body).css('user-select', 'none');
    });

    $(targetDoc).on('mousemove.acuWindowDrag' + id, (e) => {
      if (!isDragging) return;

      const dx = e.clientX - dragStartX;
      const dy = e.clientY - dragStartY;

      $window.css({
        left: Math.max(0, windowStartX + dx) + 'px',
        top: Math.max(0, windowStartY + dy) + 'px'
      });
    });

    $(targetDoc).on('mouseup.acuWindowDrag' + id, () => {
      if (isDragging) {
        isDragging = false;
        $(targetDoc.body).css('user-select', '');
      }
    });

    // 調整大小 —— 事件綁定到主窗口 document
    if (resizable) {
      let isResizing = false;
      let resizeType = '';
      let resizeStartX, resizeStartY, startWidth, startHeight, startLeft, startTop;

      $window.find('.acu-window-resize-handle').on('mousedown', function(e) {
        if (isMaximized) return;

        isResizing = true;
        resizeType = '';
        if ($(this).hasClass('se')) resizeType = 'se';
        else if ($(this).hasClass('e')) resizeType = 'e';
        else if ($(this).hasClass('s')) resizeType = 's';
        else if ($(this).hasClass('w')) resizeType = 'w';
        else if ($(this).hasClass('n')) resizeType = 'n';
        else if ($(this).hasClass('nw')) resizeType = 'nw';
        else if ($(this).hasClass('ne')) resizeType = 'ne';
        else if ($(this).hasClass('sw')) resizeType = 'sw';

        resizeStartX = e.clientX;
        resizeStartY = e.clientY;
        startWidth = $window.width();
        startHeight = $window.height();
        startLeft = parseInt($window.css('left'));
        startTop = parseInt($window.css('top'));

        $(targetDoc.body).css('user-select', 'none');
        e.stopPropagation();
      });

      $(targetDoc).on('mousemove.acuWindowResize' + id, (e) => {
        if (!isResizing) return;

        const dx = e.clientX - resizeStartX;
        const dy = e.clientY - resizeStartY;
        const minW = 400, minH = 300;

        let newW = startWidth, newH = startHeight, newL = startLeft, newT = startTop;

        if (resizeType.includes('e')) newW = Math.max(minW, startWidth + dx);
        if (resizeType.includes('s')) newH = Math.max(minH, startHeight + dy);
        if (resizeType.includes('w')) {
          const proposedW = startWidth - dx;
          if (proposedW >= minW) {
            newW = proposedW;
            newL = startLeft + dx;
          }
        }
        if (resizeType.includes('n')) {
          const proposedH = startHeight - dy;
          if (proposedH >= minH) {
            newH = proposedH;
            newT = startTop + dy;
          }
        }

        $window.css({
          width: newW + 'px',
          height: newH + 'px',
          left: newL + 'px',
          top: newT + 'px'
        });
      });

      $(targetDoc).on('mouseup.acuWindowResize' + id, () => {
        if (isResizing) {
          isResizing = false;
          $(targetDoc.body).css('user-select', '');
        }
      });
    }

    // 清理事件（窗口關閉時）
    $window.on('remove', () => {
      $(targetDoc).off('.acuWindowDrag' + id);
      $(targetDoc).off('.acuWindowResize' + id);
    });

    // 回調
    if (onReady) {
      setTimeout(() => onReady($window), 50);
    }

    return $window;
  }

  /**
   * 關閉指定窗口
   */
  function closeACUWindow(id) {
    const $window = ACU_WindowManager.getWindow(id);
    if ($window) {
      // 獲取主窗口 jQuery
      const targetWin = topLevelWindow_ACU || window;
      const $ = targetWin.jQuery || (typeof jQuery_API_ACU !== 'undefined' ? jQuery_API_ACU : null);
      if ($) {
        $(`.acu-window-overlay[data-for="${id}"]`).remove();
        // 清理事件
        $(targetWin.document).off('.acuWindowDrag' + id);
        $(targetWin.document).off('.acuWindowResize' + id);
      }
      $window.remove();
      ACU_WindowManager.unregister(id);
    }
  }

  // ═══════════════════════════════════════════════════════════════════════════════
  // ███ 獨立窗口系統結束 ███
  // ═══════════════════════════════════════════════════════════════════════════════

  // --- [Legacy] 舊版"單份設置/單份模板"存儲鍵（僅用於遷移；新版本不再直接讀寫它們） ---
  const STORAGE_KEY_CUSTOM_TEMPLATE_ACU = `${SCRIPT_ID_PREFIX_ACU}_customTemplate`; // legacy: single template
  const MENU_ITEM_CONTAINER_ID_ACU = `${SCRIPT_ID_PREFIX_ACU}-extensions-menu-container`;

  const STORAGE_KEY_ALL_SETTINGS_ACU = `${SCRIPT_ID_PREFIX_ACU}_allSettings_v2`; // legacy: single settings
  // --- [New] Profile 化存儲：全局元信息 + 按“標識代碼”分組的設置/模板 ---
  const STORAGE_KEY_GLOBAL_META_ACU = `${SCRIPT_ID_PREFIX_ACU}_globalMeta_v1`;
  const STORAGE_KEY_PROFILE_PREFIX_ACU = `${SCRIPT_ID_PREFIX_ACU}_profile_v1`;
  // --- [新增] 表格模板預設庫（多份模板存儲 + 下拉切換） ---
  const STORAGE_KEY_TEMPLATE_PRESETS_ACU = `${SCRIPT_ID_PREFIX_ACU}_templatePresets_v1`;
  const STORAGE_KEY_IMPORTED_ENTRIES_ACU = `${SCRIPT_ID_PREFIX_ACU}_importedTxtEntries`; // Key for imported TXT entries
  const STORAGE_KEY_IMPORTED_STATUS_ACU = `${SCRIPT_ID_PREFIX_ACU}_importedTxtStatus`; // [新增] Key for import status
  const STORAGE_KEY_IMPORTED_STATUS_STANDARD_ACU = `${SCRIPT_ID_PREFIX_ACU}_importedTxtStatus_standard`; // [新增] 標準模式斷點續行狀態
  const STORAGE_KEY_IMPORTED_STATUS_SUMMARY_ACU = `${SCRIPT_ID_PREFIX_ACU}_importedTxtStatus_summary`; // [新增] 總結模式斷點續行狀態
  const STORAGE_KEY_IMPORTED_STATUS_FULL_ACU = `${SCRIPT_ID_PREFIX_ACU}_importedTxtStatus_full`; // [新增] 整體模式斷點續行狀態

  // --- [新增] 設置存儲後端：優先寫入酒館設置(extensionSettings)，本地回退走 IndexedDB ---
  // 說明：
  // - 本腳本是 Tampermonkey 用戶腳本，不是標準 SillyTavern 擴展目錄，因此歷史上用 localStorage 存設置。
  // - 在 SillyTavern 環境中，我們可以把設置寫入 SillyTavern 的 extensionSettings，並調用 saveSettings() 持久化到酒館設置文件。
  // - 這裏僅遷移“腳本設置(allSettings)”與“自定義模板(customTemplate)”兩類配置；外部導入暫存仍走 IndexedDB/localStorage 兜底。
  const USE_TAVERN_SETTINGS_STORAGE_ACU = true;
  const TAVERN_SETTINGS_NAMESPACE_ACU = `${SCRIPT_ID_PREFIX_ACU}__userscript_settings_v1`;
  let tavernSaveSettingsFn_ACU = null;
  let tavernExtensionSettingsRoot_ACU = null;
  const TAVERN_BRIDGE_GLOBAL_KEY_ACU = '__ACU_USERSCRIPT_BRIDGE__';
  const TAVERN_BRIDGE_INJECTED_FLAG_ACU = '__ACU_USERSCRIPT_BRIDGE_INJECTED__';
  const sleep_ACU = (ms) => new Promise(r => setTimeout(r, ms));
  let tavernBridgeErrorReported_ACU = false;

  function tryReadBridgeFromTop_ACU() {
      try {
          const bridge = topLevelWindow_ACU?.[TAVERN_BRIDGE_GLOBAL_KEY_ACU];
          if (bridge && typeof bridge === 'object') {
              if (bridge.error && !tavernBridgeErrorReported_ACU) {
                  tavernBridgeErrorReported_ACU = true;
                  console.warn(`[${SCRIPT_ID_PREFIX_ACU}] Tavern bridge 初始化失敗：`, bridge.error);
              }
              if (bridge.extension_settings && !tavernExtensionSettingsRoot_ACU) tavernExtensionSettingsRoot_ACU = bridge.extension_settings;
              if (!tavernSaveSettingsFn_ACU) tavernSaveSettingsFn_ACU = bridge.saveSettingsDebounced || bridge.saveSettings || null;
              return !!(tavernExtensionSettingsRoot_ACU);
          }
      } catch (e) { /* ignore */ }
      return false;
  }

  async function injectTavernBridgeIntoTopWindow_ACU() {
      try {
          // 已注入則跳過
          if (topLevelWindow_ACU?.[TAVERN_BRIDGE_INJECTED_FLAG_ACU]) return true;
          topLevelWindow_ACU[TAVERN_BRIDGE_INJECTED_FLAG_ACU] = true;

          const doc = topLevelWindow_ACU.document;
          if (!doc || !doc.createElement) return false;

          const s = doc.createElement('script');
          s.type = 'module';
          s.textContent = `
              (async () => {
                  try {
                      const ext = await import('/scripts/extensions.js');
                      const main = await import('/script.js');
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'] = window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'] || {};
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'].extension_settings = ext?.extension_settings || null;
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'].saveSettingsDebounced = main?.saveSettingsDebounced || null;
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'].saveSettings = main?.saveSettings || null;
                  } catch (e) {
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'] = window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'] || {};
                      window['${TAVERN_BRIDGE_GLOBAL_KEY_ACU}'].error = String(e && (e.message || e));
                  }
              })();
          `;
          (doc.head || doc.documentElement || doc.body).appendChild(s);
          return true;
      } catch (e) {
          return false;
      }
  }

  async function initTavernSettingsBridge_ACU() {
      if (!USE_TAVERN_SETTINGS_STORAGE_ACU) return false;
      // 0) 先嚐試從頂層 bridge 讀取（最可靠：拿到真正的 extension_settings 對象）
      tryReadBridgeFromTop_ACU();
      // 0.1) 先搶救一下 saveSettings*（用於寫盤）
      try {
          if (typeof topLevelWindow_ACU.saveSettingsDebounced === 'function') tavernSaveSettingsFn_ACU = topLevelWindow_ACU.saveSettingsDebounced;
          else if (typeof window.saveSettingsDebounced === 'function') tavernSaveSettingsFn_ACU = window.saveSettingsDebounced;
          else if (typeof topLevelWindow_ACU.saveSettings === 'function') tavernSaveSettingsFn_ACU = topLevelWindow_ACU.saveSettings;
          else if (typeof window.saveSettings === 'function') tavernSaveSettingsFn_ACU = window.saveSettings;
      } catch (e) { /* ignore */ }

      // 0.5) 如果運行在 about:srcdoc iframe，直接從頂層橋接（或注入橋接）拿 extension_settings
      tryReadBridgeFromTop_ACU();
      if (!tavernExtensionSettingsRoot_ACU) {
          await injectTavernBridgeIntoTopWindow_ACU();
          // 輪詢等待 bridge 填充（最多 ~2s）
          for (let i = 0; i < 40 && !tavernExtensionSettingsRoot_ACU; i++) {
              tryReadBridgeFromTop_ACU();
              if (tavernExtensionSettingsRoot_ACU) break;
              await sleep_ACU(50);
          }
      }

      // 1) 取 saveSettings()
      try {
          const mod = await import('./script.js');
          if (mod) {
              // 優先 debounced（SillyTavern 常用寫盤方式）
              if (typeof mod.saveSettingsDebounced === 'function') tavernSaveSettingsFn_ACU = mod.saveSettingsDebounced;
              else if (typeof mod.saveSettings === 'function') tavernSaveSettingsFn_ACU = mod.saveSettings;
          }
      } catch (e) {
          // ignore
      }
      // 2) 取 extension_settings（若可用）
      try {
          const ext = await import('./scripts/extensions.js');
          if (ext && ext.extension_settings) {
              tavernExtensionSettingsRoot_ACU = ext.extension_settings;
          }
      } catch (e) {
          // ignore
      }
      // 注意：不再使用 SillyTavern.extensionSettings 作爲兜底（它在部分構建裏不一定等於可持久化的 extension_settings）
      return !!tavernExtensionSettingsRoot_ACU;
  }

  function getTavernSettingsNamespace_ACU() {
      // 同步再嘗試一次從頂層 bridge 獲取（避免 init 未等待完成）
      tryReadBridgeFromTop_ACU();
      const root = tavernExtensionSettingsRoot_ACU;
      if (!root) return null;
      if (!root.__userscripts) root.__userscripts = {};
      if (!root.__userscripts[TAVERN_SETTINGS_NAMESPACE_ACU]) root.__userscripts[TAVERN_SETTINGS_NAMESPACE_ACU] = {};
      return root.__userscripts[TAVERN_SETTINGS_NAMESPACE_ACU];
  }

  function persistTavernSettings_ACU() {
      try {
          // 同步再嘗試一次從頂層 bridge 獲取
          tryReadBridgeFromTop_ACU();
          if (typeof tavernSaveSettingsFn_ACU === 'function') {
              tavernSaveSettingsFn_ACU();
              return;
          }
          // 兜底：優先 debounced
          if (typeof topLevelWindow_ACU.saveSettingsDebounced === 'function') { topLevelWindow_ACU.saveSettingsDebounced(); return; }
          if (typeof window.saveSettingsDebounced === 'function') { window.saveSettingsDebounced(); return; }
          // 兜底：部分酒館構建可能把 saveSettings 暴露爲全局函數
          if (typeof topLevelWindow_ACU.saveSettings === 'function') topLevelWindow_ACU.saveSettings();
          else if (typeof window.saveSettings === 'function') window.saveSettings();
      } catch (e) {
          console.warn('[ACU] Failed to persist to Tavern settings. Falling back to in-memory only.', e);
      }
  }

  // --- [新增] 配置本地副本：IndexedDB（僅本瀏覽器） ---
  const CONFIG_IDB_DB_NAME_ACU = `${SCRIPT_ID_PREFIX_ACU}_config_v1`;
  const CONFIG_IDB_STORE_NAME_ACU = 'kv';
  let configIdbPromise_ACU = null;
  const configIdbCache_ACU = new Map();
  const configIdbDeletedKeys_ACU = new Set();
  let configIdbCacheLoaded_ACU = false;
  let configIdbCacheLoadingPromise_ACU = null;
  let configIdbCacheLoadFailed_ACU = false;
  let pendingSettingsReloadFromIdb_ACU = false;

  function openConfigDb_ACU() {
      if (!isIndexedDbAvailable_ACU()) return Promise.resolve(null);
      if (configIdbPromise_ACU) return configIdbPromise_ACU;
      configIdbPromise_ACU = new Promise((resolve, reject) => {
          try {
              const req = topLevelWindow_ACU.indexedDB.open(CONFIG_IDB_DB_NAME_ACU, 1);
              req.onupgradeneeded = () => {
                  const db = req.result;
                  if (!db.objectStoreNames.contains(CONFIG_IDB_STORE_NAME_ACU)) {
                      db.createObjectStore(CONFIG_IDB_STORE_NAME_ACU);
                  }
              };
              req.onsuccess = () => resolve(req.result);
              req.onerror = () => reject(req.error || new Error('IndexedDB open failed'));
          } catch (e) {
              reject(e);
          }
      });
      return configIdbPromise_ACU;
  }

  function loadConfigIdbCache_ACU() {
      if (configIdbCacheLoaded_ACU || configIdbCacheLoadFailed_ACU) return Promise.resolve();
      if (configIdbCacheLoadingPromise_ACU) return configIdbCacheLoadingPromise_ACU;
      if (!isIndexedDbAvailable_ACU()) {
          configIdbCacheLoaded_ACU = true;
          return Promise.resolve();
      }
      configIdbCacheLoadingPromise_ACU = new Promise(async (resolve) => {
          try {
              const db = await openConfigDb_ACU();
              if (!db) {
                  configIdbCacheLoaded_ACU = true;
                  resolve();
                  return;
              }
              const tx = db.transaction(CONFIG_IDB_STORE_NAME_ACU, 'readonly');
              const store = tx.objectStore(CONFIG_IDB_STORE_NAME_ACU);
              const req = store.openCursor();
              req.onsuccess = () => {
                  const cursor = req.result;
                  if (cursor) {
                      const key = cursor.key;
                      if (!configIdbDeletedKeys_ACU.has(key) && !configIdbCache_ACU.has(key)) {
                          configIdbCache_ACU.set(key, cursor.value);
                      }
                      cursor.continue();
                  } else {
                      configIdbCacheLoaded_ACU = true;
                      resolve();
                  }
              };
              req.onerror = () => {
                  console.warn('[ACU] IndexedDB config cache load failed:', req.error);
                  configIdbCacheLoadFailed_ACU = true;
                  configIdbCacheLoaded_ACU = true;
                  resolve();
              };
          } catch (e) {
              console.warn('[ACU] IndexedDB config cache load failed:', e);
              configIdbCacheLoadFailed_ACU = true;
              configIdbCacheLoaded_ACU = true;
              resolve();
          }
      });
      return configIdbCacheLoadingPromise_ACU;
  }

  function ensureConfigIdbCacheLoaded_ACU() {
      return loadConfigIdbCache_ACU();
  }

  function configIdbGetCached_ACU(key) {
      return configIdbCache_ACU.has(key) ? configIdbCache_ACU.get(key) : null;
  }

  async function configIdbSetCached_ACU(key, value) {
      configIdbCache_ACU.set(key, value);
      configIdbDeletedKeys_ACU.delete(key);
      try {
          if (!isIndexedDbAvailable_ACU()) return;
          const db = await openConfigDb_ACU();
          if (!db) return;
          const tx = db.transaction(CONFIG_IDB_STORE_NAME_ACU, 'readwrite');
          const store = tx.objectStore(CONFIG_IDB_STORE_NAME_ACU);
          await idbRequestToPromise_ACU(store.put(value, key));
      } catch (e) {
          console.warn('[ACU] IndexedDB config set failed:', e);
      }
  }

  async function configIdbRemoveCached_ACU(key) {
      configIdbCache_ACU.delete(key);
      configIdbDeletedKeys_ACU.add(key);
      try {
          if (!isIndexedDbAvailable_ACU()) return;
          const db = await openConfigDb_ACU();
          if (!db) return;
          const tx = db.transaction(CONFIG_IDB_STORE_NAME_ACU, 'readwrite');
          const store = tx.objectStore(CONFIG_IDB_STORE_NAME_ACU);
          await idbRequestToPromise_ACU(store.delete(key));
      } catch (e) {
          console.warn('[ACU] IndexedDB config delete failed:', e);
      }
  }

  function getConfigStorage_ACU() {
      const ns = USE_TAVERN_SETTINGS_STORAGE_ACU ? getTavernSettingsNamespace_ACU() : null;
      const hasTavern = !!ns;
      return {
          getItem: key => {
              if (hasTavern && Object.prototype.hasOwnProperty.call(ns, key)) return ns[key];
              const cached = configIdbGetCached_ACU(key);
              if (cached !== null && typeof cached !== 'undefined') return cached;
              if (!FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU && storage_ACU?.getItem) return storage_ACU.getItem(key);
              return null;
          },
          setItem: (key, value) => {
              const v = String(value);
              if (hasTavern) {
                  ns[key] = v;
                  persistTavernSettings_ACU();
              } else if (!FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU && storage_ACU?.setItem) {
                  storage_ACU.setItem(key, v);
              }
              void configIdbSetCached_ACU(key, v);
          },
          removeItem: key => {
              if (hasTavern) {
                  delete ns[key];
                  persistTavernSettings_ACU();
              } else if (!FORBID_BROWSER_LOCAL_STORAGE_FOR_CONFIG_ACU && storage_ACU?.removeItem) {
                  storage_ACU.removeItem(key);
              }
              void configIdbRemoveCached_ACU(key);
          },
          _isTavern: hasTavern,
      };
  }

  function migrateKeyToTavernStorageIfNeeded_ACU(key) {
      const store = getConfigStorage_ACU();
      if (!store || !store._isTavern) return false;
      const cur = store.getItem(key);
      if (cur !== null && typeof cur !== 'undefined') return false;
      if (!ALLOW_LEGACY_LOCALSTORAGE_MIGRATION_ACU || !legacyLocalStorage_ACU) return false;
      const legacy = legacyLocalStorage_ACU.getItem(key);
      if (legacy !== null && typeof legacy !== 'undefined') {
          store.setItem(key, legacy);
          try { legacyLocalStorage_ACU.removeItem(key); } catch (e) { /* ignore */ }
          return true;
      }
      return false;
  }

