  function loadTemplatePresetSelect_ACU({ globalSelectName = null, keepGlobalValue = false } = {}) {
      if (!$popupInstance_ACU || !$popupInstance_ACU.length) return;

      const presetNames = listTemplatePresetNames_ACU();
      const globalPresetName = normalizeTemplatePresetSelectionValue_ACU(getCurrentTemplatePresetName_ACU({ requireExisting: false }));
      const chatScopeState = getCurrentChatTemplateScopeState_ACU() || migrateLegacyTemplateScopeForCurrentChat_ACU();

      // 獲取當前真正生效的聊天模板名稱，並過濾掉所有舊版屎山快照名字
      let chatSelectedPresetName = normalizeTemplatePresetSelectionValue_ACU(chatScopeState?.presetName || resolveActiveTemplatePresetName_ACU({ fallbackToGlobal: true }) || '');
      if (chatSelectedPresetName.includes('舊對話歷史') || chatSelectedPresetName.includes('舊版表頭') || chatSelectedPresetName.includes('舊版聊天')) {
          chatSelectedPresetName = ''; 
      }

      const $globalSelect = getTemplatePresetSelectJQ_ACU();
      const $chatSelect = getTemplateChatPresetSelectJQ_ACU();
      const $globalStatus = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-template-global-scope-status`);
      const $chatStatus = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-template-chat-scope-status`);
      const $chatOriginStatus = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-template-chat-origin-status`);
      const $globalDeleteBtn = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-template-preset-delete`);
      const $chatDeleteBtn = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-template-chat-delete-preset`);

      // --- 處理全局下拉 ---
      populateTemplatePresetSelectOptions_ACU($globalSelect, {
          extraPresetName: (globalPresetName && !presetNames.includes(globalPresetName)) ? globalPresetName : ''
      });
      if ($globalSelect && $globalSelect.length) {
          let resolvedGlobalValue = globalSelectName !== null ? normalizeTemplatePresetSelectionValue_ACU(globalSelectName) : (keepGlobalValue ? normalizeTemplatePresetSelectionValue_ACU($globalSelect.val()) : globalPresetName);
          $globalSelect.val(resolvedGlobalValue || DEFAULT_TEMPLATE_PRESET_OPTION_VALUE_ACU);
      }

      // --- 處理當前聊天下拉 (極簡直觀化，加上後綴) ---
      if ($chatSelect && $chatSelect.length) {
          $chatSelect.empty().append(jQuery_API_ACU('<option/>').val(DEFAULT_TEMPLATE_PRESET_OPTION_VALUE_ACU).text('默認預設'));

          const allChatOptions = new Set([...presetNames]);
          if (chatSelectedPresetName) allChatOptions.add(chatSelectedPresetName);

          Array.from(allChatOptions).sort().forEach(name => {
              if (!name) return;
              // 加上 (目前聊天模板) 後綴
              const displayText = (name === chatSelectedPresetName) ? `${name} (目前聊天模板)` : name;
              $chatSelect.append(jQuery_API_ACU('<option/>').val(name).text(displayText));
          });

          $chatSelect.val(chatSelectedPresetName || DEFAULT_TEMPLATE_PRESET_OPTION_VALUE_ACU);
      }

      // --- 按鈕狀態 ---
      if ($globalDeleteBtn && $globalDeleteBtn.length) {
          $globalDeleteBtn.toggle(!!globalPresetName && presetNames.includes(globalPresetName));
      }
      if ($chatDeleteBtn && $chatDeleteBtn.length) {
          const currentChatVal = normalizeTemplatePresetSelectionValue_ACU($chatSelect.val());
          const isDefault = !currentChatVal || currentChatVal === DEFAULT_TEMPLATE_PRESET_OPTION_VALUE_ACU;

          $chatDeleteBtn.prop('disabled', isDefault);
          if (isDefault) {
              $chatDeleteBtn.css({ opacity: 0.4, cursor: 'not-allowed' }).attr('title', '默認預設不可刪除');
          } else {
              $chatDeleteBtn.css({ opacity: 1, cursor: 'pointer' }).attr('title', '徹底刪除此模板');
          }
      }

      // --- 極簡文本顯示 ---
      if ($globalStatus && $globalStatus.length) {
          $globalStatus.text(`全局模板：${globalPresetName || '默認預設'}`);
      }
      if ($chatStatus && $chatStatus.length) {
          $chatStatus.text(`當前聊天模板：${chatSelectedPresetName || '默認預設'}`);
      }
      if ($chatOriginStatus && $chatOriginStatus.length) {
          $chatOriginStatus.text('提示：切換即可應用。若刪除正在使用的模板，將自動恢復爲「默認預設」。');
      }
