  /**
   * 執行正文優化流程（在GENERATION_ENDED後調用）
   * @param {number} messageIndex - AI消息索引
   * @returns {Promise<boolean>} 是否成功
   */
  async function executeContentOptimization_ACU(messageIndex) {
    const config = settings_ACU.contentOptimizationSettings || {};
    contentOptimizationAbortRequested_ACU = false;

    // 檢查是否啓用
    if (!config.enabled) {
      return false;
    }

    const chat = SillyTavern_API_ACU.chat;
    if (!chat || !chat[messageIndex]) {
      return false;
    }

    const message = chat[messageIndex];

    // 跳過用戶消息
    if (message.is_user) {
      return false;
    }

    let content = message.mes || '';
    setLastOptimizationBase_ACU({
      messageIndex,
      messageId: message.message_id,
      baseContent: content
    });

    // [新增] 獲取用戶消息（用於$8佔位符）
    let userMessage = '';
    for (let i = messageIndex - 1; i >= 0; i--) {
      if (chat[i] && chat[i].is_user) {
        userMessage = chat[i].mes || '';
        break;
      }
    }

    const extractTags = (config.extractTags || '').trim();
    const extractRules = config.extractRules || [];
    const excludeTags = (config.excludeTags || '').trim();
    const excludeRules = config.excludeRules || [];

    let processedContent = applyContextTagFilters_ACU(content, {
      extractTags,
      extractRules,
      excludeTags,
      excludeRules
    });

    const minLength = config.minLength || 100;
    if (processedContent.length < minLength) {
      logDebug_ACU(`[正文優化] 處理後正文長度 ${processedContent.length} 小於最小閾值 ${minLength}，跳過優化`);
      return false;
    }

    const loopCount = config.loopCount || 1;
    logDebug_ACU(`[正文優化] 開始優化消息 ${messageIndex}，原始長度 ${content.length}，處理後長度 ${processedContent.length}，循環次數: ${loopCount}`);

    if (config.seamlessMode) {
      showOptimizationOverlay_ACU(loopCount > 1 ? `正在優化正文 (1/${loopCount})...` : '正在優化正文...');
    } else {
      showOptimizationProgressToast_ACU(loopCount > 1 ? `正在進行正文優化 (1/${loopCount})...` : '正在進行正文優化...');
    }

    try {
      ensureOptimizationNotCancelled_ACU();
      if (config.autoApply || config.seamlessMode) {
        let currentContent = content;
        let totalOptimizations = [];
        let finalOptimizedContent = content;

        for (let loop = 1; loop <= loopCount; loop++) {
          ensureOptimizationNotCancelled_ACU();
          logDebug_ACU(`[正文優化] 執行第 ${loop}/${loopCount} 輪優化`);

          if (config.seamlessMode && loopCount > 1) {
            showOptimizationOverlay_ACU(`正在優化正文 (${loop}/${loopCount})...`);
          } else if (!config.seamlessMode) {
            showOptimizationProgressToast_ACU(`正在進行正文優化 (${loop}/${loopCount})...`);
          }

          const result = await performContentOptimization_ACU(currentContent, {
            currentLoop: loop,
            userMessage: userMessage
          });
          ensureOptimizationNotCancelled_ACU();

          if (!result.success) {
            logDebug_ACU(`[正文優化] 第 ${loop} 輪優化失敗:`, result.error);
            if (loop === 1) {
              if (config.seamlessMode) {
                hideOptimizationOverlay_ACU();
              } else {
                hideOptimizationProgressToast_ACU();
              }
              return false;
            }
            break;
          }

          if (!result.optimizations || result.optimizations.length === 0) {
            logDebug_ACU(`[正文優化] 第 ${loop} 輪無需優化，原文已足夠好`);
            if (loop === 1) {
              if (config.seamlessMode) {
                hideOptimizationOverlay_ACU();
              } else {
                hideOptimizationProgressToast_ACU();
              }
              return true;
            }
            break;
          }

          totalOptimizations = totalOptimizations.concat(result.optimizations);
          finalOptimizedContent = result.optimizedContent;
          currentContent = result.optimizedContent;

          logDebug_ACU(`[正文優化] 第 ${loop} 輪完成，本輪 ${result.optimizations.length} 個優化項，累計 ${totalOptimizations.length} 個`);
        }

        if (totalOptimizations.length === 0) {
          logDebug_ACU('[正文優化] 所有輪次均無需優化');
          if (config.seamlessMode) {
            hideOptimizationOverlay_ACU();
          } else {
            hideOptimizationProgressToast_ACU();
          }
          return true;
        }

        await replaceChatMessage_ACU(messageIndex, finalOptimizedContent);

        if (config.seamlessMode) {
          hideOptimizationOverlay_ACU();
        } else {
          hideOptimizationProgressToast_ACU();
        }

        if (config.showDiff && !config.seamlessMode) {
          showOptimizationDiff_ACU(messageIndex, {
            optimizations: totalOptimizations,
            summary: `共 ${loopCount} 輪優化，累計 ${totalOptimizations.length} 處改進`,
            optimizedContent: finalOptimizedContent
          });
        } else {
          showToastr_ACU('success', `正文優化完成，共 ${loopCount} 輪優化，累計 ${totalOptimizations.length} 處改進`);
        }

        return true;
      } else {
        hideOptimizationProgressToast_ACU();
        return await executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, loopCount);
      }

    } catch (error) {
      if (contentOptimizationAbortRequested_ACU || error?.message === '用戶終止正文優化') {
        logDebug_ACU('[正文優化] 用戶已取消正文優化');
        return false;
      }
      logError_ACU('[正文優化] 執行出錯:', error);
      if (config.seamlessMode) {
        hideOptimizationOverlay_ACU();
      } else {
        hideOptimizationProgressToast_ACU();
      }
      return false;
    } finally {
      hideOptimizationOverlay_ACU();
      hideOptimizationProgressToast_ACU();
      contentOptimizationAbortRequested_ACU = false;
    }
  }

  /**
   * 執行正文優化（手動確認模式，逐輪確認）
   * @param {number} messageIndex - 消息索引
   * @param {string} content - 原始內容
   * @param {string} userMessage - 用戶消息
   * @param {number} totalLoops - 總循環次數
   * @param {number} currentLoop - 當前循環次數（內部使用）
   * @param {string} currentContent - 當前內容（內部使用）
   * @param {Array} totalOptimizations - 累計優化項（內部使用）
   * @returns {Promise<boolean>} 是否成功
   */
  async function executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop = 1, currentContent = null, totalOptimizations = []) {
    // 使用傳入的當前內容，或者原始內容
    let workingContent = currentContent !== null ? currentContent : content;

    logDebug_ACU(`[正文優化-手動確認] 執行第 ${currentLoop}/${totalLoops} 輪優化`);

    // 執行優化
    const result = await performContentOptimization_ACU(workingContent, {
      currentLoop: currentLoop,
      userMessage: userMessage
    });

    if (!result.success) {
      logDebug_ACU(`[正文優化-手動確認] 第 ${currentLoop} 輪優化失敗:`, result.error);
      // 如果是第一輪就失敗，顯示錯誤
      if (currentLoop === 1) {
        showToastr_ACU('error', `正文優化失敗: ${result.error}`);
        return false;
      }
      // 如果是後續輪次失敗，使用之前的結果觸發填表
      await triggerAutomaticUpdateIfNeeded_ACU();
      return true;
    }

    // 檢查是否有實際優化
    if (!result.optimizations || result.optimizations.length === 0) {
      logDebug_ACU(`[正文優化-手動確認] 第 ${currentLoop} 輪無需優化，原文已足夠好`);
      // 如果沒有優化項，檢查是否還有下一輪
      if (currentLoop < totalLoops) {
        // 繼續下一輪（使用當前內容）
        return await executeContentOptimizationWithConfirm_ACU(messageIndex, content, userMessage, totalLoops, currentLoop + 1, workingContent, totalOptimizations);
      } else {
        // 所有輪次完成，觸發填表
        if (totalOptimizations.length > 0) {
          showToastr_ACU('success', `正文優化完成，共 ${totalLoops} 輪優化，累計 ${totalOptimizations.length} 處改進`);
        } else {
          showToastr_ACU('info', '正文無需優化');
        }
        await triggerAutomaticUpdateIfNeeded_ACU();
        return true;
      }
    }

    // 累積優化項
    const newTotalOptimizations = totalOptimizations.concat(result.optimizations);

    // 顯示對比對話框
    return new Promise((resolve) => {
      showOptimizationDiffDialogForLoop_ACU(messageIndex, {
        optimizations: result.optimizations,
        summary: `第 ${currentLoop}/${totalLoops} 輪優化，本輪 ${result.optimizations.length} 處改進`,
        optimizedContent: result.optimizedContent,
        currentLoop: currentLoop,
        totalLoops: totalLoops,
        totalOptimizations: newTotalOptimizations
      }, async (action) => {
        if (action === 'apply') {
          // 用戶確認應用
          if (currentLoop < totalLoops) {
            // 還有下一輪，繼續優化
            const nextResult = await executeContentOptimizationWithConfirm_ACU(
              messageIndex,
              content,
              userMessage,
              totalLoops,
              currentLoop + 1,
              result.optimizedContent,
              newTotalOptimizations
            );
            resolve(nextResult);
          } else {
            // 所有輪次完成，應用最終結果並觸發填表
            await replaceChatMessage_ACU(messageIndex, result.optimizedContent);
            showToastr_ACU('success', `正文優化完成，共 ${totalLoops} 輪優化，累計 ${newTotalOptimizations.length} 處改進`);
            await triggerAutomaticUpdateIfNeeded_ACU();
            resolve(true);
          }
        } else if (action === 'skip') {
          // 用戶跳過本輪，但繼續下一輪
          if (currentLoop < totalLoops) {
            const nextResult = await executeContentOptimizationWithConfirm_ACU(
              messageIndex,
              content,
              userMessage,
              totalLoops,
              currentLoop + 1,
              workingContent,  // 使用未優化的內容
              totalOptimizations  // 不累積本輪優化項
            );
            resolve(nextResult);
          } else {
            // 最後一輪跳過
            if (totalOptimizations.length > 0) {
              // 如果有之前的優化，應用之前的結果
              // 注意：這裏需要應用之前累積的優化內容
              await triggerAutomaticUpdateIfNeeded_ACU();
              showToastr_ACU('success', `正文優化完成，共 ${totalLoops} 輪優化，累計 ${totalOptimizations.length} 處改進`);
            } else {
              showToastr_ACU('info', '正文優化已跳過');
            }
            await triggerAutomaticUpdateIfNeeded_ACU();
            resolve(true);
          }
        } else {
          // 用戶取消，結束優化流程
          await triggerAutomaticUpdateIfNeeded_ACU();
          resolve(true);
        }
      });
    });
  }

