      // 先保存當前 profile 的設置（模板通常在修改時已單獨保存；這裏不強制重寫模板以減少寫入量）
      try { saveSettings_ACU(); } catch (e) {}

      // 更新 globalMeta：當前標識 + 跨標識共享的列表
      loadGlobalMeta_ACU();
