    /**
     * 通過前端直接導入表格模板（無需文件選擇器）
     * @param {Object|string} templateData - 模板數據，可以是 JSON 對象或 JSON 字符串
     * @param {Object} options - 可選配置
     * @param {'global'|'chat'} options.scope - 導入作用域，默認 global
     * @param {string} options.presetName - 僅當 scope=global 時可選保存到預設庫；scope=chat 時僅寫入聊天快照元信息
     * @returns {Promise<{success: boolean, message: string, scope?: string, presetName?: string}>} 導入結果
     */
    importTemplateFromData: async function(templateData, options = {}) {
        try {
            const { scope = 'global', presetName = '' } = options || {};
            const normalizedScope = normalizeTemplateOperationScope_ACU(scope);
            const normalizedPresetName = deriveTemplatePresetNameForImport_ACU({
                presetName,
                fallbackLabel: normalizedScope === 'global'
                    ? `導入模板_${new Date().toISOString().slice(0, 19).replace(/[:T]/g, '-')}`
                    : '',
            });
            const prepared = parseImportedTemplateData_ACU(templateData);

            if (normalizedScope === 'global' && normalizedPresetName) {
                const savePresetOk = upsertTemplatePreset_ACU(normalizedPresetName, prepared.templateStr);
                if (!savePresetOk) {
                    return {
                        success: false,
                        scope: normalizedScope,
                        message: `模板已解析，但保存全局模板預設失敗：${normalizedPresetName}`,
                    };
                }
            }

            const applied = await applyTemplateSnapshotToScope_ACU(prepared.templateStr, {
                scope: normalizedScope,
                source: normalizedScope === 'chat' ? 'api_import_template_chat' : 'api_import_template_global',
                presetName: normalizedPresetName,
                refreshUi: !!$popupInstance_ACU,
                save: true,
                persistChatScope: normalizedScope === 'chat',
            });
            if (!applied) {
                return {
                    success: false,
                    scope: normalizedScope,
                    message: '模板導入失敗：無法應用模板快照。',
                };
            }

            logDebug_ACU(`[API] importTemplateFromData: 模板已成功導入到${normalizedScope === 'chat' ? '當前聊天' : '全局'}。`);
            return {
                success: true,
                scope: normalizedScope,
                message: normalizedScope === 'chat'
                    ? `模板已成功導入到當前聊天${normalizedPresetName ? `（預設名：${normalizedPresetName}）` : ''}！`
                    : (normalizedPresetName
                        ? `模板已成功導入到全局，並已保存爲預設：${normalizedPresetName}`
                        : '模板已成功導入到全局！'),
                presetName: normalizedPresetName || undefined,
            };

        } catch (e) {
            logError_ACU('importTemplateFromData failed:', e);
            return { success: false, message: `導入失敗: ${e.message}` };
        }
    },

    /**
     * 通過前端直接導入劇情推進預設（無需文件選擇器）
     * @param {Object|string} presetData - 預設數據，可以是 JSON 對象或 JSON 字符串
     * @param {Object} options - 可選配置
     * @param {boolean} options.overwrite - 如果預設已存在，是否覆蓋（默認 false，會自動重命名）
     * @param {boolean} options.switchTo - 導入後是否立即切換到該預設（默認 false）
     * @returns {Promise<{success: boolean, message: string, presetName?: string}>} 導入結果
     */
    importPlotPresetFromData: async function(presetData, options = {}) {
        try {
            const { overwrite = false, switchTo = false } = options;
            let preset;

            // 支持字符串或對象格式
            if (typeof presetData === 'string') {
                try {
                    preset = JSON.parse(presetData);
                } catch (parseError) {
                    return { success: false, message: `JSON解析錯誤: ${parseError.message}` };
                }
            } else if (typeof presetData === 'object' && presetData !== null) {
                preset = JSON.parse(JSON.stringify(presetData)); // 深拷貝
            } else {
                return { success: false, message: '無效的預設數據：必須是 JSON 對象或 JSON 字符串' };
            }

            // 驗證預設數據必須包含 name 字段
            if (!preset.name || typeof preset.name !== 'string' || preset.name.trim() === '') {
                return { success: false, message: '預設數據無效：缺少 "name" 字段或名稱爲空' };
            }

            const presetName = preset.name.trim();
            const presets = settings_ACU.plotSettings?.promptPresets || [];
            const existingIndex = presets.findIndex(p => p.name === presetName);
            const normalizedPreset = normalizePlotPresetExcludeRules_ACU(preset);
            normalizedPreset.name = presetName;

            let finalName = presetName;

            if (existingIndex !== -1) {
                if (overwrite) {
                    // 覆蓋現有預設
                    presets[existingIndex] = normalizedPreset;
                    logDebug_ACU(`[API] importPlotPresetFromData: 覆蓋已存在的預設 "${presetName}"`);
                } else {
                    // 自動重命名
                    let counter = 1;
                    while (presets.some(p => p.name === finalName)) {
                        finalName = `${presetName} (${counter})`;
                        counter++;
                    }
                    normalizedPreset.name = finalName;
                    presets.push(normalizedPreset);
                    logDebug_ACU(`[API] importPlotPresetFromData: 預設已存在，重命名爲 "${finalName}"`);
                }
            } else {
                // 新增預設
                presets.push(normalizedPreset);
                logDebug_ACU(`[API] importPlotPresetFromData: 新增預設 "${presetName}"`);
            }

            settings_ACU.plotSettings.promptPresets = presets;
            saveSettings_ACU();

            let switchedCurrentChat = false;
            // 如果需要，導入到全局預設庫後再切換當前對話使用該預設
            if (switchTo) {
                switchedCurrentChat = this.injectPlotPresetToCurrentChat(finalName) === true;
            }

            // 如果設置面板已打開，刷新預設選擇器
            if ($popupInstance_ACU && !switchTo) {
                loadPlotPresetSelect_ACU();
            }

            return {
                success: true,
                message: switchedCurrentChat
                    ? `預設 "${finalName}" 已成功導入到全局預設庫，並已切換當前聊天使用該預設。`
                    : `預設 "${finalName}" 已成功導入到全局預設庫！`,
                presetName: finalName,
            };

        } catch (e) {
            logError_ACU('importPlotPresetFromData failed:', e);
            return { success: false, message: `導入失敗: ${e.message}` };
        }
    },

    /**
     * 批量導入多個劇情推進預設
     * @param {Array<Object|string>} presetsArray - 預設數據數組
     * @param {Object} options - 可選配置
     * @param {boolean} options.overwrite - 如果預設已存在，是否覆蓋（默認 false）
     * @returns {Promise<{success: boolean, message: string, imported: number, failed: number, details: Array}>} 導入結果
     */
    importPlotPresetsFromData: async function(presetsArray, options = {}) {
        try {
            if (!Array.isArray(presetsArray)) {
                return { success: false, message: '輸入必須是數組', imported: 0, failed: 0, details: [] };
            }

            const details = [];
            let imported = 0;
            let failed = 0;

            for (const presetData of presetsArray) {
                const result = await this.importPlotPresetFromData(presetData, { ...options, switchTo: false });
                details.push(result);
                if (result.success) {
                    imported++;
                } else {
                    failed++;
                }
            }

            return {
                success: failed === 0,
                message: `批量導入完成：成功 ${imported} 個，失敗 ${failed} 個`,
                imported,
                failed,
                details
            };

        } catch (e) {
            logError_ACU('importPlotPresetsFromData failed:', e);
            return { success: false, message: `批量導入失敗: ${e.message}`, imported: 0, failed: 0, details: [] };
        }
    },

