    // =========================
    // 遊戲初始化 API（角色卡開場頁面專用）
    // =========================

    /**
     * 遊戲初始化接口 - 供角色卡開場頁面調用
     * @param {Object} characterData - 角色數據
     * @param {Object} options - 配置選項
     * @returns {Promise<Object>} 初始化結果
     */
    initGameSession: async function(characterData, options = {}) {
        const result = {
            success: false,
            templateInjected: false,
            presetLoaded: false,
            protagonistInitialized: false,
            equipmentInitialized: false,
            message: ''
        };

        try {
            // 步驟1: 注入數據庫模板到首樓
            if (options.injectTemplate !== false) {
                logDebug_ACU('[遊戲初始化] 開始注入數據庫模板...');
                try {
                    let templateData;

                    // 優先使用傳入的 templateData 參數
                    if (options.templateData) {
                        logDebug_ACU('[遊戲初始化] 使用傳入的模板數據');
                        templateData = options.templateData;
                    } else {
                        // 從服務器加載默認模板
                        logDebug_ACU('[遊戲初始化] 從服務器加載模板數據');
                        const templateResponse = await fetch('/TavernDB_template_默認模板.json');
                        if (!templateResponse.ok) {
                            throw new Error(`HTTP ${templateResponse.status}: ${templateResponse.statusText}`);
                        }
                        templateData = await templateResponse.json();
                    }

                    // 將模板數據直接填充到第一樓（包含所有種子數據）
                    const templateObj = typeof templateData === 'string' ? JSON.parse(templateData) : templateData;
                    const templatePresetName = deriveTemplatePresetNameForImport_ACU({
                        presetName: options.templatePresetName || characterData?.name || characterData?.data?.name || '',
                    });
                    const fillResult = await fillFirstLayerWithTemplateData_ACU(templateObj, {
                        reason: 'game_init',
                        presetName: templatePresetName,
                        source: 'game_init',
                        registerPreset: true,
                    });
                    if (fillResult) {
                        result.templateInjected = true;
                        logDebug_ACU('[遊戲初始化] 數據庫模板注入成功（包含種子數據）');
                    } else {
                        // 回退到舊方式（僅寫入指導表）
                        await overwriteChatSheetGuideFromTemplate_ACU(templateObj, {
                            reason: 'game_init',
                            presetName: templatePresetName,
                            source: 'game_init',
                            syncTemplateScope: true,
                            registerPreset: true,
                        });
                        result.templateInjected = true;
                        logDebug_ACU('[遊戲初始化] 數據庫模板注入成功（僅指導表）');
                    }
                } catch (templateError) {
                    logError_ACU('[遊戲初始化] 模板注入失敗:', templateError);
                    throw new Error(`數據庫模板注入失敗: ${templateError.message}`);
                }
            }

            // 步驟2: 加載劇情引導預設
            if (options.loadPreset !== false) {
                logDebug_ACU('[遊戲初始化] 開始加載劇情引導預設...');
                const presetName = options.presetName || '西幻劇情引導';
                try {
                    let presetData;

                    // 優先使用傳入的 presetData 參數
                    if (options.presetData) {
                        logDebug_ACU('[遊戲初始化] 使用傳入的預設數據');
                        presetData = options.presetData;
                    } else {
                        // 從服務器加載預設數據
                        logDebug_ACU('[遊戲初始化] 從服務器加載預設數據');
                        const presetResponse = await fetch('/西幻劇情引導.json');
                        if (!presetResponse.ok) {
                            throw new Error(`HTTP ${presetResponse.status}: ${presetResponse.statusText}`);
                        }
                        presetData = await presetResponse.json();
                    }

                    // 導入預設
                    const importResult = await this.importPlotPresetFromData(presetData, {
                        overwrite: true,
                        switchTo: true
                    });
                    if (!importResult.success) {
                        throw new Error(importResult.message || '預設導入失敗');
                    }
                    result.presetLoaded = true;
                    logDebug_ACU('[遊戲初始化] 劇情引導預設加載成功');
                } catch (presetError) {
                    logError_ACU('[遊戲初始化] 預設加載失敗:', presetError);
                    // 預設加載失敗不阻斷流程，只記錄警告
                    logWarn_ACU('[遊戲初始化] 劇情引導預設加載失敗，但繼續遊戲初始化');
                }
            }

            // 步驟3: 保存設置並刷新
            try {
                saveSettings_ACU();
                if (topLevelWindow_ACU.AutoCardUpdaterAPI && topLevelWindow_ACU.AutoCardUpdaterAPI._notifyTableUpdate) {
                    topLevelWindow_ACU.AutoCardUpdaterAPI._notifyTableUpdate();
                }
            } catch (saveError) {
                logWarn_ACU('[遊戲初始化] 保存設置時出錯:', saveError);
            }

            result.success = true;
            result.message = '遊戲初始化成功';
            logDebug_ACU('[遊戲初始化] 遊戲初始化流程完成');

        } catch (error) {
            result.message = `初始化失敗: ${error.message}`;
            logError_ACU('initGameSession failed:', error);
        }

        return result;
    },

