   // [新增] 清理超出保留層數的舊本地數據（表格數據 + 劇情推進數據）
   // 按AI樓層計數，僅保留最近N層的數據，更早樓層的 TavernDB_ACU_* 和 qrf_plot 字段將被刪除
   // [重要] 此函數不會刪除聊天第一層的"空白指導表"（TavernDB_ACU_InternalSheetGuide），
   //        指導表用於保存表頭結構和填表參數，作爲該聊天的總指導。
   async function purgeOldLayerData_ACU() {
       const retainCount = settings_ACU.retainRecentLayers || 0;
       // 0 或空 = 全部保留，不執行清理
       if (retainCount <= 0) {
           logDebug_ACU('[數據清理] retainRecentLayers 爲 0 或未設置，跳過清理。');
           return;
       }

       const chat = SillyTavern_API_ACU?.chat;
       if (!chat || !Array.isArray(chat) || chat.length === 0) {
           logDebug_ACU('[數據清理] 聊天記錄爲空，跳過清理。');
           return;
       }

       // 1) 收集所有 包含本地數據(TavernDB_ACU_Data/qrf_plot) 的消息索引（按時間順序，從舊到新）
       // [保護] 排除 chat[0]，確保第一層的指導表數據不被觸及
       // [修改] 適配用戶層保存邏輯：不再僅檢查 AI 消息，而是檢查所有可能包含數據的消息（包括用戶消息）
       const dataMessageIndices = [];
       for (let i = 1; i < chat.length; i++) {
           const msg = chat[i];
           // 檢查是否包含本插件生成的任何本地數據
           if (msg && (
               msg.TavernDB_ACU_Data ||
               msg.TavernDB_ACU_SummaryData ||
               msg.qrf_plot
           )) {
               dataMessageIndices.push(i);
           }
       }

       if (dataMessageIndices.length <= retainCount) {
           logDebug_ACU(`[數據清理] 含數據消息總數(${dataMessageIndices.length}) <= 保留層數(${retainCount})，無需清理。`);
           return;
       }

       // 2) 確定需要清理的樓層：保留最近 retainCount 層，清理更早的
      const cutoffIndex = dataMessageIndices.length - retainCount; // 從這個位置開始是要保留的
      // [優化] 移除"永遠保留第一層"的邏輯，嚴格按照填寫的樓層數來保留數據
      const indicesToPurge = dataMessageIndices.slice(0, cutoffIndex); // 這些是要清理的

      if (indicesToPurge.length === 0) {
          logDebug_ACU('[數據清理] 無需清理的樓層。');
           return;
       }

       logDebug_ACU(`[數據清理] 將清理 ${indicesToPurge.length} 層消息的本地數據（保留最近 ${retainCount} 層）...`);

       // 3) 遍歷需要清理的樓層，刪除本地數據字段
       let purgedCount = 0;
       const keysToDelete = [
           'TavernDB_ACU_Data',
           'TavernDB_ACU_SummaryData',
           'TavernDB_ACU_IndependentData',
           'TavernDB_ACU_ModifiedKeys',
           'TavernDB_ACU_UpdateGroupKeys',
           'TavernDB_ACU_IsolatedData',
           'TavernDB_ACU_Identity',
           'qrf_plot',
           'qrf_plot_preset'  // [新增] 清理劇情規劃預設名稱標籤
       ];

       for (const idx of indicesToPurge) {
           const msg = chat[idx];
           if (!msg) continue;

           let modified = false;
           for (const key of keysToDelete) {
               if (msg.hasOwnProperty(key)) {
                   delete msg[key];
                   modified = true;
               }
           }

           if (modified) {
               purgedCount++;
           }
       }

       if (purgedCount > 0) {
           // 4) 保存聊天記錄
           try {
               await SillyTavern_API_ACU.saveChat();
               logDebug_ACU(`[數據清理] 已清理 ${purgedCount} 層AI消息的本地數據，聊天記錄已保存。`);
               // [優化] 移除自動清理後的提示框，避免打擾用戶
           } catch (e) {
               logError_ACU('[數據清理] 保存聊天記錄失敗:', e);
           }
       } else {
           logDebug_ACU('[數據清理] 目標樓層中未發現需要清理的數據字段。');
       }
   }

