  async function fetchModelsAndConnect_ACU() {
    if (
      !$popupInstance_ACU ||
      !$customApiUrlInput_ACU ||
      !$customApiKeyInput_ACU ||
      !$customApiModelSelect_ACU ||
      !$apiStatusDisplay_ACU
    ) {
      logError_ACU('加載模型列表失敗：UI元素未初始化。');
      showToastr_ACU('error', 'UI未就緒。');
      return;
    }
    const apiUrl = $customApiUrlInput_ACU.val().trim();
    const apiKey = $customApiKeyInput_ACU.val();
    if (!apiUrl) {
      showToastr_ACU('warning', '請輸入API基礎URL。');
      $apiStatusDisplay_ACU.text('狀態:請輸入API基礎URL').css('color', 'orange');
      return;
    }
    const statusUrl = `/api/backends/chat-completions/status`;
    $apiStatusDisplay_ACU.text('狀態: 正在檢查API端點狀態...').css('color', '#61afef');
    showToastr_ACU('info', '正在檢查自定義API端點狀態...');

    try {
        const body = {
            "reverse_proxy": apiUrl,
            "proxy_password": "",
            "chat_completion_source": "custom",
            "custom_url": apiUrl,
            "custom_include_headers": apiKey ? `Authorization: Bearer ${apiKey}` : ""
        };

        const response = await fetch(statusUrl, {
            method: 'POST',
            headers: { ...SillyTavern.getRequestHeaders(), 'Content-Type': 'application/json' },
            body: JSON.stringify(body)
        });

        if (!response.ok) {
            const errorText = await response.text();
            let errorMessage = `API端點狀態檢查失敗: ${response.status} ${response.statusText}.`;
            try {
                const errorJson = JSON.parse(errorText);
                errorMessage += ` 詳情: ${errorJson.error || errorJson.message || errorText}`;
            } catch (e) {
                errorMessage += ` 詳情: ${errorText}`;
            }
            throw new Error(errorMessage);
        }

      const data = await response.json();
      logDebug_ACU('獲取到的模型數據:', data);
      // 保存當前選中的模型
      const currentSelectedModel = settings_ACU.apiConfig.model || '';
      // 清空select並添加默認選項
      $customApiModelSelect_ACU.empty().append('<option value="">-- 請選擇模型 --</option>');
      let modelsFound = false;
      let modelsList = [];
      if (data && data.models && Array.isArray(data.models)) {
          // Format from Tavern's status endpoint: { models: [...] }
          modelsList = data.models;
      } else if (data && data.data && Array.isArray(data.data)) {
          // Format from OpenAI /v1/models endpoint: { data: [{id: ...}] }
          modelsList = data.data;
      } else if (Array.isArray(data)) {
          // Format from some providers that return a direct array: [...]
          modelsList = data;
      }

      if (modelsList.length > 0) {
        modelsFound = true;
        modelsList.forEach(model => {
          const modelName = typeof model === 'string' ? model : model.id;
          if (modelName) {
            const selected = modelName === currentSelectedModel ? ' selected' : '';
            $customApiModelSelect_ACU.append(`<option value="${escapeHtml_ACU(modelName)}"${selected}>${escapeHtml_ACU(modelName)}</option>`);
          }
        });
      }

      if (modelsFound) {
        // 如果之前保存的模型不在列表中，也添加進去
        if (currentSelectedModel && $customApiModelSelect_ACU.find(`option[value="${escapeHtml_ACU(currentSelectedModel)}"]`).length === 0) {
            $customApiModelSelect_ACU.append(`<option value="${escapeHtml_ACU(currentSelectedModel)}" selected>${escapeHtml_ACU(currentSelectedModel)} (已保存)</option>`);
        }
        showToastr_ACU('success', `模型列表加載成功！共加載 ${modelsList.length} 個模型。`);
      } else {
        showToastr_ACU('warning', '未能解析模型數據或列表爲空。');
        $apiStatusDisplay_ACU.text('狀態: 未能解析模型數據或列表爲空。').css('color', 'orange');
      }
    } catch (error) {
      logError_ACU('加載模型列表時出錯:', error);
      showToastr_ACU('error', `加載模型列表失敗: ${error.message}`);
      $apiStatusDisplay_ACU.text(`狀態: 加載模型失敗 - ${error.message}`).css('color', '#ff6b6b');
    }
    updateApiStatusDisplay_ACU();
  }
