                                            <i class="fa-solid fa-copy"></i><span>另存為</span>
                                        </button>
                                        <button id="${SCRIPT_ID_PREFIX_ACU}-template-chat-reset-preset" class="acu-mini-btn" title="取消當前聊天綁定，恢復為默認預設" style="color: var(--orange);">
                                            <i class="fa-solid fa-undo"></i><span>恢復默認</span>
                                        </button>
                                        <button id="${SCRIPT_ID_PREFIX_ACU}-template-chat-import-preset" class="acu-mini-btn" title="導入模板套用於當前聊天">
