                refreshTemplatePresetUiState_ACU({ globalSelectName: name, keepGlobalValue: true });
                showToastr_ACU('success', `全局默認模板已指定為：${displayName} (將於新開聊天時生效)`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.IMPORT });
            });
        }

        // 右側：當前聊天下拉選單切換 (實質套用)
        if ($templateChatPresetSelect_ACU && $templateChatPresetSelect_ACU.length) {
            $templateChatPresetSelect_ACU.off('change.acu_template_preset').on('change.acu_template_preset', async function() {
                const name = normalizeTemplatePresetSelectionValue_ACU(jQuery_API_ACU(this).val());
                const displayName = name || '默認預設';
                showToastr_ACU('info', `正在套用模板至當前聊天：${displayName}...`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.IMPORT });
                const result = await applyTemplatePresetToCurrent_ACU(name, {
                    source: 'ui_chat_select',
                    updateGlobal: false, // 絕不污染全局
                    refreshUi: true,
                    save: true,
                    persistChatScope: true,
                });
                if (result) {
                    refreshTemplatePresetUiState_ACU({ keepGlobalValue: true });
                    showToastr_ACU('success', `當前聊天已套用模板：${displayName}`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.IMPORT });
                } else {
                    showToastr_ACU('error', `模板套用失敗：${displayName}`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR });
                    refreshTemplatePresetUiState_ACU({ keepGlobalValue: true });
                }
            });
        }

        // 💥 【徹底解耦】左側：保存到全局 (只存入倉庫，不套用至當前)
        if ($templatePresetSaveBtn_ACU && $templatePresetSaveBtn_ACU.length) {
            $templatePresetSaveBtn_ACU.off('click.acu_template_preset').on('click.acu_template_preset', async function() {
                const currentSelectedName = normalizeTemplatePresetSelectionValue_ACU(jQuery_API_ACU($templatePresetSelect_ACU).val());
                let finalName = currentSelectedName;
                if (isDefaultTemplatePresetSelection_ACU(currentSelectedName)) {
                    const promptedName = prompt('請輸入要保存的全局模板名稱：', '新全局模板');
                    if (!promptedName) return;
                    finalName = String(promptedName).trim();
                } else if (!confirm(`確定要把目前編輯中的結構，覆蓋到倉庫裡的 "${currentSelectedName}" 嗎？\n(這不會改變你當前聊天的綁定狀態)`)) {
                    return;
                }
                if (!finalName) return;
                const norm = normalizeTemplateForPresetSave_ACU();
                if (!norm) {
                    showToastr_ACU('error', '保存失敗：無法解析當前模板。', { acuToastCategory: ACU_TOAST_CATEGORY_ACU.ERROR });
                    return;
                }

                // 只寫入倉庫
                upsertTemplatePreset_ACU(finalName, norm.templateStr);
                persistCurrentTemplatePresetName_ACU(finalName, { save: true });

                refreshTemplatePresetUiState_ACU({ globalSelectName: finalName, keepGlobalValue: true });
                showToastr_ACU('success', `已存入全局庫：${finalName}`, { acuToastCategory: ACU_TOAST_CATEGORY_ACU.IMPORT });
            });
        }

        // 左側：另存為
        if ($templatePresetSaveAsBtn_ACU && $templatePresetSaveAsBtn_ACU.length) {
            $templatePresetSaveAsBtn_ACU.off('click.acu_template_preset').on('click.acu_template_preset', async function() {
                const cur = normalizeTemplatePresetSelectionValue_ACU(jQuery_API_ACU($templatePresetSelect_ACU).val());
                const defaultName = cur ? `${cur}_副本` : '新模板預設';
                const raw = prompt('另存為新的全局模板名稱：', defaultName);
                if (!raw || !String(raw).trim()) return;

                const norm = normalizeTemplateForPresetSave_ACU();
                if (!norm) return;

                const finalName = ensureUniqueTemplatePresetName_ACU(String(raw).trim());
                upsertTemplatePreset_ACU(finalName, norm.templateStr);
                persistCurrentTemplatePresetName_ACU(finalName, { save: true });

                refreshTemplatePresetUiState_ACU({ globalSelectName: finalName, keepGlobalValue: true });
