                if (!newName || !String(newName).trim()) return;

                const nn = ensureUniqueTemplatePresetName_ACU(String(newName).trim());
                const norm = normalizeTemplateForPresetSave_ACU();
                if (!norm) return;

                // 寫入新名字到全局庫
