        `#${SCRIPT_ID_PREFIX_ACU}-plot-extract-tags`,
        `#${SCRIPT_ID_PREFIX_ACU}-plot-min-length`,
        `#${SCRIPT_ID_PREFIX_ACU}-plot-task-stage`,
