      // 匹配替換速率保存
      const plotRateInputs = [
        { id: 'plot-rate-main', key: 'rateMain', defaultValue: 1.0 },
        { id: 'plot-rate-personal', key: 'ratePersonal', defaultValue: 1.0 },
        { id: 'plot-rate-erotic', key: 'rateErotic', defaultValue: 0 },
