      if (!$popupInstance_ACU) return {};

      flushCurrentPlotTaskEditorState_ACU({ renderTaskList: true, persist: false });
      const activeSettings = getActivePlotEditorSettings_ACU();
      const currentSettings = JSON.parse(JSON.stringify(activeSettings || settings_ACU.plotSettings || {}));
      ensurePlotTasksCompat_ACU(currentSettings, { syncLegacy: true });

      delete currentSettings.promptPresets;
      delete currentSettings.lastUsedPresetName;
      delete currentSettings.enabled;

      const promptGroup = getPlotPromptGroupFromSource_ACU(currentSettings);
      const legacyPromptTexts = getLegacyPromptTextsFromPromptGroup_ACU(promptGroup);
      currentSettings.promptGroup = promptGroup;
      currentSettings.finalSystemDirective = $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-final-directive`).val() || '';
      currentSettings.mainPrompt = legacyPromptTexts.mainPrompt || '';
      currentSettings.systemPrompt = legacyPromptTexts.systemPrompt || '';
      currentSettings.rateMain = parseFloat($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-rate-main`).val()) || 1.0;
      currentSettings.ratePersonal = parseFloat($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-rate-personal`).val()) || 1.0;
      currentSettings.rateErotic = parseFloat($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-rate-erotic`).val()) || 0;
      currentSettings.rateCuckold = parseFloat($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-rate-cuckold`).val()) || 1.0;
      currentSettings.recallCount = parseInt($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-recall-count`).val(), 10) || 20;
      currentSettings.contextExtractRules = readExcludeRulesFromRows_ACU(`#${SCRIPT_ID_PREFIX_ACU}-plot-context-extract-rules`);
      currentSettings.contextExcludeRules = readExcludeRulesFromRows_ACU(`#${SCRIPT_ID_PREFIX_ACU}-plot-context-exclude-rules`);
      currentSettings.contextTurnCount = parseInt($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-context-turn-count`).val(), 10) || 3;
      currentSettings.loopSettings = {
        ...(currentSettings.loopSettings || {}),
        quickReplyContent: (() => {
          const prompts = [];
          $popupInstance_ACU.find('.loop-prompt-textarea').each(function() {
            const content = $(this).val()?.trim() || '';
            if (content) prompts.push(content);
          });
          return prompts;
        })(),
        currentPromptIndex: 0,
        loopTags: $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-loop-tags`).val() || '',
        loopDelay: parseInt($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-loop-delay`).val(), 10) || 5,
        loopTotalDuration: parseInt($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-loop-total-duration`).val(), 10) || 0,
        maxRetries: parseInt($popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-max-retries`).val(), 10) || 3,
      };

      currentSettings.plotTasks = normalizePlotTasks_ACU(currentSettings);
      ensurePlotPromptsArray_ACU(currentSettings);
      setPlotPromptContentByIdForSettings_ACU(currentSettings, 'mainPrompt', currentSettings.mainPrompt || '');
      setPlotPromptContentByIdForSettings_ACU(currentSettings, 'systemPrompt', currentSettings.systemPrompt || '');
      setPlotPromptContentByIdForSettings_ACU(currentSettings, 'finalSystemDirective', currentSettings.finalSystemDirective || '');
      ensurePlotTasksCompat_ACU(currentSettings, { syncLegacy: true });
      currentSettings.finalSystemDirective = getPlotPromptContentByIdFromSettings_ACU(currentSettings, 'finalSystemDirective') || currentSettings.finalSystemDirective || '';

      return currentSettings;
    }

    /**
     * 另存爲新的全局預設
     */
    function savePlotPresetAsNew_ACU() {
      const presetName = prompt('請輸入新的全局預設名稱：');
      const name = String(presetName || '').trim();
      if (!name) return;

      const presets = settings_ACU.plotSettings.promptPresets || [];
      const existingIndex = presets.findIndex(p => p.name === name);

      const currentSettings = getCurrentPlotSettingsFromUI_ACU();
      if (!currentSettings || typeof currentSettings !== 'object') {
        showToastr_ACU('error', '讀取當前劇情推進設置失敗。');
        return;
      }

      const savedPreset = normalizePlotPresetExcludeRules_ACU({ name, ...currentSettings });
      if (existingIndex !== -1) {
        if (!confirm(`名爲 "${name}" 的全局預設已存在。是否要覆蓋它？`)) {
          return;
        }
        presets[existingIndex] = savedPreset;
      } else {
        presets.push(savedPreset);
      }

      settings_ACU.plotSettings.promptPresets = presets;
      const currentRuntimePresetName = getCurrentRuntimePlotPresetName_ACU({ fallbackToGlobal: true });
      const currentChatBinding = getPlotPresetBindingForChat_ACU();
      const hasLegacyChatScope = !!getCurrentChatPlotScopeState_ACU();
      const shouldRefreshCurrentChatRuntime =
        normalizePlotPresetSelectionValue_ACU(currentRuntimePresetName) === name ||
        (!currentChatBinding && !hasLegacyChatScope);

      if (shouldRefreshCurrentChatRuntime) {
        applyPlotPresetToSettings_ACU(settings_ACU.plotSettings, savedPreset);
      }

      setCurrentEditablePlotPresetState_ACU(name, {
        scope: 'global',
        source: 'ui_global_save_as_new',
      });
      persistPlotPresetSelectionState_ACU(name, { source: 'ui_global_save_as_new', updateGlobal: true, save: false });
      saveSettings_ACU();

      loadPlotPresetSelect_ACU();
      $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-global-preset-select`).val(name);
      $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-plot-global-delete-preset`).show();

      showToastr_ACU('success', `新全局預設 "${name}" 已保存。`);
    }
  }

  // Removed updateAdvancedHideUIDisplay_ACU function

  async function updateCardUpdateStatusDisplay_ACU() {
    const $totalMessagesDisplay = $popupInstance_ACU
      ? $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-total-messages-display`)
      : null;
    const $statusTableBody = $popupInstance_ACU
      ? $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-granular-status-table-body`)
      : null;
    const $nextUpdateDisplay = $popupInstance_ACU
      ? $popupInstance_ACU.find(`#${SCRIPT_ID_PREFIX_ACU}-next-update-display`)
      : null;

    if (
      !$popupInstance_ACU ||
      !$cardUpdateStatusDisplay_ACU ||
      !$cardUpdateStatusDisplay_ACU.length ||
      !$totalMessagesDisplay ||
      !$totalMessagesDisplay.length ||
      !$statusTableBody ||
      !$statusTableBody.length
    ) {
      logDebug_ACU('updateCardUpdateStatusDisplay_ACU: UI elements not ready.');
      return;
    }

    const chatHistory = SillyTavern_API_ACU.chat || [];
    const totalMessages = chatHistory.filter(msg => !msg.is_user).length;
    $totalMessagesDisplay.text(`上下文總層數: ${totalMessages} (僅計算AI回覆樓層)`);

    const totalAiMessages = totalMessages;

    if (!currentJsonTableData_ACU) {
      $cardUpdateStatusDisplay_ACU.text('數據庫狀態：未加載或初始化失敗。');
      $statusTableBody.html('<tr><td colspan="5" style="text-align: center;">暫無數據</td></tr>');
      return;
    }

    try {
      const sheetKeys = getSortedSheetKeys_ACU(currentJsonTableData_ACU);
      const tableCount = sheetKeys.length;
      let totalRowCount = 0;
      let nextUpdates = [];
      let tableStatusRows = "";

      sheetKeys.forEach(key => {
        const table = currentJsonTableData_ACU[key];
        if (!table) return;

        if (table.content && Array.isArray(table.content)) {
            totalRowCount += table.content.length > 1 ? table.content.length - 1 : 0;
        }

        // 計算每個表的狀態
        const tableConfig = table.updateConfig || {};
        const isSummary = isSummaryOrOutlineTable_ACU(table.name);

        // 確定參數
        const globalFrequency = settings_ACU.autoUpdateFrequency || 1;
        const globalSkip = settings_ACU.skipUpdateFloors || 0;

        // -1 = 沿用UI全局；0 = 禁用該表自動更新（不參與預測）
        const rawFreq = Number.isFinite(tableConfig.updateFrequency) ? tableConfig.updateFrequency : -1;
        const rawSkip = Number.isFinite(tableConfig.skipFloors) ? tableConfig.skipFloors : -1;
        const frequency = (rawFreq === -1) ? globalFrequency : rawFreq;

        // [重構] 上次更新樓層計算：掃描聊天記錄
        // 尋找該表格在歷史記錄中最後一次被更新的樓層
        // 支持合併更新邏輯：只要合併更新組內有任意表被修改，整組表都視爲已更新
        let lastUpdatedAiFloor = 0;
        let foundInHistory = false;

        // [數據隔離核心] 獲取當前隔離標籤鍵名
        const currentIsolationKey = getCurrentIsolationKey_ACU();

        for (let i = chatHistory.length - 1; i >= 0; i--) {
             const msg = chatHistory[i];
             if (msg.is_user) continue;

             let wasUpdated = false;

             // [優先級1] 檢查新版按標籤分組存儲 TavernDB_ACU_IsolatedData
             if (msg.TavernDB_ACU_IsolatedData && msg.TavernDB_ACU_IsolatedData[currentIsolationKey]) {
                 const tagData = msg.TavernDB_ACU_IsolatedData[currentIsolationKey];
                 const modifiedKeys = tagData.modifiedKeys || [];
                 const updateGroupKeys = tagData.updateGroupKeys || [];
                 const independentData = tagData.independentData || {};

                 if (updateGroupKeys.length > 0 && modifiedKeys.length > 0) {
                     wasUpdated = updateGroupKeys.includes(key);
                 } else if (modifiedKeys.length > 0) {
                     wasUpdated = modifiedKeys.includes(key);
                 } else if (independentData[key]) {
                     wasUpdated = true;
                 }
             }

             // [優先級2] 兼容舊版存儲格式 - 嚴格匹配隔離標籤
             if (!wasUpdated) {
                 const msgIdentity = msg.TavernDB_ACU_Identity;
                 let isLegacyMatch = false;
                 if (settings_ACU.dataIsolationEnabled) {
                     isLegacyMatch = (msgIdentity === settings_ACU.dataIsolationCode);
                 } else {
                     // 關閉隔離（無標籤模式）：只匹配無標識數據
                     isLegacyMatch = !msgIdentity;
                 }

                 if (isLegacyMatch) {
                     const modifiedKeys = msg.TavernDB_ACU_ModifiedKeys || [];
                     const updateGroupKeys = msg.TavernDB_ACU_UpdateGroupKeys || [];

                     if (updateGroupKeys.length > 0 && modifiedKeys.length > 0) {
                         wasUpdated = updateGroupKeys.includes(key);
                     } else if (modifiedKeys.length > 0) {
                         wasUpdated = modifiedKeys.includes(key);
                     } else {
                         // 舊版兼容：沒有 ModifiedKeys 字段時，回退到檢查數據是否存在
                         if (msg.TavernDB_ACU_IndependentData && msg.TavernDB_ACU_IndependentData[key]) {
                             wasUpdated = true;
                         }
                         else if (isSummary && msg.TavernDB_ACU_SummaryData && msg.TavernDB_ACU_SummaryData[key]) {
                             wasUpdated = true;
                         }
                         else if (!isSummary && msg.TavernDB_ACU_Data && msg.TavernDB_ACU_Data[key]) {
                             wasUpdated = true;
                         }
                     }
                 }
             }

             if (wasUpdated) {
                 // 計算這是第幾個 AI 回覆
                 lastUpdatedAiFloor = chatHistory.slice(0, i + 1).filter(m => !m.is_user).length;
                 foundInHistory = true;
                 break;
             }
        }

        const skipFloors = Math.max(0, (rawSkip === -1) ? globalSkip : rawSkip);

        // 下次觸發 (包含skip)
        let triggerFloor = "N/A";
        let unrecorded = "N/A";
        let effectiveUnrecorded = "N/A"; // [修復] 在外部作用域聲明變量
        let isReady = false;

        const isAutoUpdateDisabledForThisTable = (frequency <= 0);

        if (isAutoUpdateDisabledForThisTable) {
            // 頻率=0：不參與自動更新，UI顯示“無”
            triggerFloor = '無';
            // 仍可展示“未記錄樓層/上次更新”，便於用戶觀察數據變化
            if (foundInHistory) {
                unrecorded = totalAiMessages - lastUpdatedAiFloor;
                effectiveUnrecorded = '—';
            } else {
                unrecorded = '—';
                effectiveUnrecorded = '—';
            }
            isReady = false;
        } else if (foundInHistory) {
            // [修復] UI顯示邏輯同步修正
            // 觸發樓層 = 上次更新樓層 + 頻率 + 跳過樓層
            triggerFloor = lastUpdatedAiFloor + frequency + skipFloors;

            // 顯示給用戶的未記錄樓層：直接展示物理差值
            unrecorded = totalAiMessages - lastUpdatedAiFloor;

            // 有效積累樓層（用於判斷進度）：減去跳過樓層
            effectiveUnrecorded = Math.max(0, (totalAiMessages - skipFloors) - lastUpdatedAiFloor);

            isReady = effectiveUnrecorded >= frequency;

            // 將數值存入預測數組
            nextUpdates.push({ name: table.name, floor: triggerFloor, isReady });
        }

        // 顯示文本處理
        let lastUpdatedDisplay = foundInHistory ? lastUpdatedAiFloor : '<span style="color: grey;">未初始</span>';

        // 高亮顯示當前層更新的表，並顯示變更數量
        const isUpdatedThisFloor = foundInHistory && (lastUpdatedAiFloor === totalAiMessages);

        if (isUpdatedThisFloor) {
            const changes = table._lastUpdateStats ? table._lastUpdateStats.changes : 0;
            const changeText = changes > 0 ? `(+${changes})` : '(無變更)';
            lastUpdatedDisplay = `<span style="color: lightgreen; font-weight: bold;">${lastUpdatedAiFloor} ${changeText}</span>`;
        }

        tableStatusRows += `
            <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
                <td style="text-align: left; padding: 5px;">${escapeHtml_ACU(table.name)}</td>
                <td style="text-align: center; padding: 5px;">${frequency}</td>
                <td style="text-align: center; padding: 5px;" title="有效未記錄: ${effectiveUnrecorded}">${unrecorded}</td>
                <td style="text-align: center; padding: 5px;">${lastUpdatedDisplay}</td>
                <td style="text-align: center; padding: 5px;">${triggerFloor}</td>
            </tr>
        `;
      });

      $statusTableBody.html(tableStatusRows);

      $cardUpdateStatusDisplay_ACU.html(`數據庫狀態: <b style="color:lightgreen;">已加載</b> (${tableCount}個表格, ${totalRowCount}條記錄)`);

      // 更新下次預測顯示
      if ($nextUpdateDisplay.length && nextUpdates.length > 0) {
          nextUpdates.sort((a, b) => a.floor - b.floor);
          const readyList = nextUpdates.filter(u => u.isReady);
          const upcomingList = nextUpdates.filter(u => !u.isReady);

          let statusText = "";
          if (readyList.length > 0) {
               statusText += `<span style="color: lightgreen;">[就緒] ${readyList.map(u => u.name).join(', ')}</span> `;
          }

          if (upcomingList.length > 0) {
              const next = upcomingList[0];
              const othersSameFloor = upcomingList.filter(u => u.floor === next.floor && u !== next);
              let names = next.name;
              if (othersSameFloor.length > 0) names += ", " + othersSameFloor.map(u => u.name).join(", ");

              if (statusText) statusText += " | ";
              statusText += `下一次: <b>${names}</b> (AI樓層 ${next.floor})`;
          } else if (readyList.length === 0) {
               statusText = "下一次: <b>無</b>";
          }

          $nextUpdateDisplay.html(statusText);
      } else if ($nextUpdateDisplay.length) {
          // 所有表都禁用自動更新 / 沒有可參與預測的表
          $nextUpdateDisplay.html("下一次: <b>無</b>");
      }

    } catch (e) {
      logError_ACU('ACU: Failed to parse database for UI status:', e);
      $cardUpdateStatusDisplay_ACU.text('解析數據庫狀態時出錯。');
    }
  }

  async function loadAllChatMessages_ACU() {
    if (!coreApisAreReady_ACU || !TavernHelper_API_ACU) return;
    try {
      const lastMessageId = TavernHelper_API_ACU.getLastMessageId
        ? TavernHelper_API_ACU.getLastMessageId()
        : SillyTavern_API_ACU.chat?.length
        ? SillyTavern_API_ACU.chat.length - 1
        : -1;
      if (lastMessageId < 0) {
        allChatMessages_ACU = [];
        logDebug_ACU('No chat messages (ACU).');
        return;
      }
      const messagesFromApi = await TavernHelper_API_ACU.getChatMessages(`0-${lastMessageId}`, {
        include_swipes: false,
      });
      if (messagesFromApi && messagesFromApi.length > 0) {
        allChatMessages_ACU = messagesFromApi.map((msg, idx) => ({ ...msg, id: idx })); // Add simple index for now
        logDebug_ACU(`ACU Loaded ${allChatMessages_ACU.length} messages for: ${currentChatFileIdentifier_ACU}.`);
      } else {
        allChatMessages_ACU = [];
      }
    } catch (error) {
      logError_ACU('ACU獲取聊天記錄失敗: ' + error.message);
      allChatMessages_ACU = [];
    }
  }

  // --- [新增] 世界書相關功能 ---

  async function getWorldbookNames_ACU() {
      if (TavernHelper_API_ACU && typeof TavernHelper_API_ACU.getLorebooks === 'function') {
          const bookNames = await Promise.resolve(TavernHelper_API_ACU.getLorebooks());
          return (Array.isArray(bookNames) ? bookNames : [])
              .map(name => String(name || '').trim())
              .filter(Boolean);
      }
      if (SillyTavern_API_ACU && typeof SillyTavern_API_ACU.getWorldBooks === 'function') {
          const books = await SillyTavern_API_ACU.getWorldBooks();
          return (Array.isArray(books) ? books : [])
              .map(book => String(book?.name || '').trim())
              .filter(Boolean);
      }
      return [];
  }

  async function getLorebookEntriesByNames_ACU(bookNames = []) {
      const uniqueNames = [...new Set((Array.isArray(bookNames) ? bookNames : []).map(name => String(name || '').trim()).filter(Boolean))];
      const entriesMap = {};
      const canUseTavernHelper = TavernHelper_API_ACU && typeof TavernHelper_API_ACU.getLorebookEntries === 'function';
      let fallbackBooks = null;

      if (!canUseTavernHelper && SillyTavern_API_ACU && typeof SillyTavern_API_ACU.getWorldBooks === 'function') {
          fallbackBooks = await SillyTavern_API_ACU.getWorldBooks();
      }

      for (const name of uniqueNames) {
          try {
              let entries = [];
              if (canUseTavernHelper) {
                  entries = await TavernHelper_API_ACU.getLorebookEntries(name);
              } else if (Array.isArray(fallbackBooks)) {
                  const matchedBook = fallbackBooks.find(book => book?.name === name);
                  entries = matchedBook?.entries || [];
              }
              entriesMap[name] = Array.isArray(entries) ? entries.map(entry => ({ ...entry, book: name })) : [];
          } catch (e) {
              logWarn_ACU(`[Worldbook] 獲取世界書 "${name}" 條目失敗（忽略該書，繼續）：`, e);
              entriesMap[name] = [];
          }
      }
      return entriesMap;
  }

  async function getWorldBooks_ACU() {
      const bookNames = await getWorldbookNames_ACU();
      const entriesMap = await getLorebookEntriesByNames_ACU(bookNames);
      return bookNames.map(name => ({
          name,
          entries: Array.isArray(entriesMap[name]) ? entriesMap[name] : [],
      }));
  }

  function isImportTaggedLorebookEntry_ACU(entry) {
    const rawComment = String(entry?.comment || entry?.name || '').trim();
    if (!rawComment) return false;
    const normalizedComment = rawComment.replace(/^ACU-\[[^\]]+\]-/, '');
    return normalizedComment.startsWith(getImportStablePrefix_ACU());
  }

  function getWorldbookCommentInfo_ACU(entry) {
      const rawComment = String(entry?.comment || entry?.name || '').trim();
      let normalizedComment = rawComment.replace(/^ACU-\[[^\]]+\]-/, '');
      normalizedComment = normalizedComment.replace(/^外部導入-(?:[^-]+-)?/, '');
      return { rawComment, normalizedComment };
  }

  function getWorldbookEntryKeywords_ACU(entry) {
      const toStrArray = v => {
          if (Array.isArray(v)) return v.filter(x => typeof x === 'string' && x.trim());
          if (typeof v === 'string' && v.trim()) return [v];
          return [];
      };
      return [...new Set([...toStrArray(entry?.key), ...toStrArray(entry?.keys)])].map(k => k.toLowerCase());
  }

  function getWorldbookEntryPlaceholderSortKey_ACU(entry) {
      const position = normalizeLorebookPosition_ACU(entry?.position, 'at_depth_as_system');
      const order = getEntryOrderNumber_ACU(entry);
      const normalizedOrder = order === null ? Number.MAX_SAFE_INTEGER : order;
      const depthValue = typeof entry?.depth === 'number' ? entry.depth : parseInt(String(entry?.depth ?? ''), 10);
      const normalizedDepth = Number.isFinite(depthValue) ? depthValue : 0;

      if (position === 'before_character_definition') {
          return { segment: 0, depthRank: 0, order: normalizedOrder };
      }
      if (position === 'after_character_definition') {
          return { segment: 1, depthRank: 0, order: normalizedOrder };
      }
      return { segment: 2, depthRank: -normalizedDepth, order: normalizedOrder };
  }

  function compareWorldbookEntriesForPlaceholder_ACU(a, b) {
      const keyA = getWorldbookEntryPlaceholderSortKey_ACU(a);
      const keyB = getWorldbookEntryPlaceholderSortKey_ACU(b);

      if (keyA.segment !== keyB.segment) return keyA.segment - keyB.segment;
      if (keyA.depthRank !== keyB.depthRank) return keyA.depthRank - keyB.depthRank;
      if (keyA.order !== keyB.order) return keyA.order - keyB.order;

      const originalIndexA = Number.isFinite(a?._acuPlaceholderOriginalIndex) ? a._acuPlaceholderOriginalIndex : Number.MAX_SAFE_INTEGER;
      const originalIndexB = Number.isFinite(b?._acuPlaceholderOriginalIndex) ? b._acuPlaceholderOriginalIndex : Number.MAX_SAFE_INTEGER;
      if (originalIndexA !== originalIndexB) return originalIndexA - originalIndexB;

      const bookNameA = String(a?.bookName || '');
      const bookNameB = String(b?.bookName || '');
      if (bookNameA !== bookNameB) return bookNameA.localeCompare(bookNameB, 'zh-Hans-CN');

      const uidA = String(a?.uid ?? '');
      const uidB = String(b?.uid ?? '');
      return uidA.localeCompare(uidB, 'zh-Hans-CN');
  }

  async function buildCombinedWorldbookContentByStrategy_ACU(options = {}) {
      const logPrefix = String(options?.logPrefix || '[Worldbook]');
      const bookNames = [...new Set((Array.isArray(options?.bookNames) ? options.bookNames : []).map(name => String(name || '').trim()).filter(Boolean))];
      const includeEntry = typeof options?.includeEntry === 'function' ? options.includeEntry : () => true;
      const isSelected = typeof options?.isSelected === 'function' ? options.isSelected : () => true;
      const excludeDisabledEntries = options?.excludeDisabledEntries !== false;
      const includeConstantEntriesInBaseScan = options?.includeConstantEntriesInBaseScan === true;
      const formatEntry = typeof options?.formatEntry === 'function'
          ? options.formatEntry
          : (entry => `# ${entry.comment || `Entry from ${entry.bookName}`}\n${entry.content}`);
      const sortEntries = typeof options?.sortEntries === 'function' ? options.sortEntries : compareWorldbookEntriesForPlaceholder_ACU;

      if (bookNames.length === 0) {
          logWarn_ACU(`${logPrefix} 沒有找到任何世界書，內容將爲空`);
          return '';
      }

      const entriesMap = await getLorebookEntriesByNames_ACU(bookNames);
      let allEntries = [];
      let placeholderOriginalIndex = 0;
      for (const bookName of bookNames) {
          const bookEntries = Array.isArray(entriesMap[bookName]) ? entriesMap[bookName] : [];
          logDebug_ACU(`${logPrefix} 世界書 "${bookName}" 條目數量:`, bookEntries.length);
          bookEntries.forEach(entry => {
              const { rawComment, normalizedComment } = getWorldbookCommentInfo_ACU(entry);
              const decoratedEntry = {
                  ...entry,
                  bookName,
                  rawComment,
                  normalizedComment,
                  _acuPlaceholderOriginalIndex: placeholderOriginalIndex++,
              };
              if (includeEntry(decoratedEntry) === false) return;
              allEntries.push(decoratedEntry);
          });
      }

      if (typeof options?.onEntriesFiltered === 'function') {
          try { options.onEntriesFiltered(allEntries); } catch (e) {}
      }
      if (allEntries.length === 0) {
          logDebug_ACU(`${logPrefix} 所選世界書在過濾後無可用條目。`);
          return '';
      }

      let userEnabledEntries = allEntries.filter(entry => (excludeDisabledEntries ? !!entry.enabled : true));
      userEnabledEntries = userEnabledEntries.filter(entry => isSelected(entry) !== false);
      if (typeof options?.onSelectedEntries === 'function') {
          try { options.onSelectedEntries(userEnabledEntries); } catch (e) {}
      }
      if (userEnabledEntries.length === 0) {
          logDebug_ACU(`${logPrefix} 當前配置下沒有啓用的世界書條目。`);
          return '';
      }

      let baseScanText = '';
      if (typeof options?.baseScanText === 'string' && options.baseScanText.trim()) {
          baseScanText = options.baseScanText;
      } else if (typeof options?.fallbackScanText === 'string' && options.fallbackScanText.trim()) {
          baseScanText = options.fallbackScanText;
      }
      baseScanText = baseScanText.toLowerCase();

      const constantEntries = userEnabledEntries.filter(entry => entry.type === 'constant');
      let keywordEntries = userEnabledEntries.filter(entry => entry.type !== 'constant');

      if (includeConstantEntriesInBaseScan) {
          const constantBaseText = constantEntries
              .filter(entry => !entry.prevent_recursion)
              .map(entry => entry.content || '')
              .join('\n')
              .toLowerCase();
          if (constantBaseText) {
              baseScanText = [baseScanText, constantBaseText].filter(Boolean).join('\n');
          }
      }

      const triggeredEntries = new Set([...constantEntries]);
      let recursionDepth = 0;
      const MAX_RECURSION_DEPTH = 10;

      while (recursionDepth < MAX_RECURSION_DEPTH) {
          recursionDepth++;
          let hasChangedInThisPass = false;

          const recursionSourceContent = Array.from(triggeredEntries)
              .filter(entry => !entry.prevent_recursion)
              .map(entry => entry.content)
              .join('\n')
              .toLowerCase();
          const fullSearchText = `${baseScanText}\n${recursionSourceContent}`;

          const remainingKeywordEntries = [];
          for (const entry of keywordEntries) {
              const keywords = getWorldbookEntryKeywords_ACU(entry);
              const isTriggered = keywords.length > 0 && keywords.some(keyword =>
                  entry.exclude_recursion ? baseScanText.includes(keyword) : fullSearchText.includes(keyword)
              );

              if (isTriggered) {
                  triggeredEntries.add(entry);
                  hasChangedInThisPass = true;
              } else {
                  remainingKeywordEntries.push(entry);
              }
          }

          if (!hasChangedInThisPass) {
              logDebug_ACU(`${logPrefix} Worldbook recursion stabilized after ${recursionDepth} passes.`);
              break;
          }

          keywordEntries = remainingKeywordEntries;
      }

      if (recursionDepth >= MAX_RECURSION_DEPTH) {
          logWarn_ACU(`${logPrefix} Worldbook recursion reached max depth of ${MAX_RECURSION_DEPTH}. Breaking loop.`);
      }

      let finalEntries = Array.from(triggeredEntries);
      if (sortEntries) {
          finalEntries = finalEntries.sort(sortEntries);
      }

      const finalContent = finalEntries
          .map(entry => formatEntry(entry))
          .filter(chunk => typeof chunk === 'string' && chunk.trim());

      if (finalContent.length === 0) {
          logDebug_ACU(`${logPrefix} No worldbook entries were ultimately triggered.`);
          return '';
      }

      const combinedContent = finalContent.join('\n\n').trim();
      logDebug_ACU(`${logPrefix} Combined worldbook content generated, length: ${combinedContent.length}. ${finalEntries.length} entries triggered.`);
      return combinedContent;
  }

  async function getCombinedWorldbookContent_ACU(initialScanTextOverride = '', options = {}) {
    logDebug_ACU('Starting to get combined worldbook content with advanced logic...');
    const worldbookConfig = getCurrentWorldbookConfig_ACU();
    const excludeImportTaggedEntries = options?.excludeImportTaggedEntries === true;

    if (!TavernHelper_API_ACU || !SillyTavern_API_ACU) {
        logWarn_ACU('[ACU] TavernHelper or SillyTavern API not available, cannot get worldbook content.');
        return '';
    }

    try {
        let bookNames = [];

        if (worldbookConfig.source === 'manual') {
            bookNames = worldbookConfig.manualSelection || [];
        } else { // 'character' mode
            try {
                const charLorebooks = await TavernHelper_API_ACU.getCharLorebooks({ type: 'all' });
                if (charLorebooks.primary) bookNames.push(charLorebooks.primary);
                if (charLorebooks.additional?.length) bookNames.push(...charLorebooks.additional);
            } catch (e) {
                logError_ACU('[Worldbook] 獲取角色世界書失敗:', e);
                return '';
            }
        }

        const enabledEntriesMap = worldbookConfig?.enabledEntries;
        const hasAnySelection = enabledEntriesMap && typeof enabledEntriesMap === 'object' && Object.keys(enabledEntriesMap).length > 0;
        return await buildCombinedWorldbookContentByStrategy_ACU({
            logPrefix: '[Worldbook]',
            bookNames,
            baseScanText: (typeof initialScanTextOverride === 'string' && initialScanTextOverride.trim()) ? initialScanTextOverride : '',
            fallbackScanText: allChatMessages_ACU.map(message => message.message).join('\n'),
            includeEntry: entry => {
                const comment = entry.comment || '';
                if (comment.startsWith('TavernDB-ACU-')) return false;
                if (comment.startsWith('重要人物條目')) return false;
                if (comment.startsWith('總結條目')) return false;
                if (excludeImportTaggedEntries && isImportTaggedLorebookEntry_ACU(entry)) return false;
                if (isEntryBlocked_ACU(entry)) return false;
                return true;
            },
            isSelected: entry => {
                if (!hasAnySelection) return true;
                const list = enabledEntriesMap?.[entry.bookName];
                if (typeof list === 'undefined') return true;
                if (!Array.isArray(list)) return true;
                return list.includes(entry.uid);
            },
            onEntriesFiltered: entries => {
                if (excludeImportTaggedEntries) {
                    logDebug_ACU(`[Worldbook][Import] Import prompt exclusion enabled. Remaining entries after excluding import-tagged lorebook items: ${entries.length}`);
                }
            },
        });

    } catch (error) {
        logError_ACU(`[ACU] An error occurred while processing worldbook logic:`, error);
        return ''; // Return empty string on error to prevent breaking the generation.
    }
  }
  // --- [新增] 世界書相關功能結束 ---

  async function prepareAIInput_ACU(messages, updateMode = 'standard', targetSheetKeys = null, options = {}) {
    // updateMode: 'standard' 表示更新標準表，'summary' 表示更新總結表和總體大綱
    // targetSheetKeys: 可選，指定要更新的表格key列表
    // This function is now simplified to only prepare the dynamic content parts.
    // The main prompt assembly will happen in callCustomOpenAI_ACU.
    if (!currentJsonTableData_ACU) {
        logError_ACU('prepareAIInput_ACU: Cannot prepare AI input, currentJsonTableData_ACU is null.');
        return null;
    }

    // [修復] 生成 $0 之前，確保 seedRows 可用（新對話首次填表、或指導表未命中時也能兜底）
    // - 只把 seedRows 掛到表對象字段，不寫入 content
    let _seedGuideDataForThisPrepare_ACU = null;
    try {
        _seedGuideDataForThisPrepare_ACU = await ensureChatSheetGuideSeeded_ACU({ reason: 'prepare_ai_input_seedrows' });
        if (_seedGuideDataForThisPrepare_ACU) {
            attachSeedRowsToCurrentDataFromGuide_ACU(_seedGuideDataForThisPrepare_ACU);
        }
    } catch (e) {}

    // 1. Format the current JSON table data into a human-readable text block for $0
    let tableDataText = '';
    let _seedRowsTablesUsed_ACU = [];
    const tableIndexes = getSortedSheetKeys_ACU(currentJsonTableData_ACU);
    tableIndexes.forEach((sheetKey, tableIndex) => {
        const table = currentJsonTableData_ACU[sheetKey];
        if (!table || !table.name || !table.content) return;

        // [獨立更新檢查] 如果指定了 targetSheetKeys，則嚴格過濾
        if (targetSheetKeys && Array.isArray(targetSheetKeys)) {
            if (!targetSheetKeys.includes(sheetKey)) return;
        }

        // [新增] 根據更新模式和表格名稱決定是否顯示數據行
        // 注意：如果 targetSheetKeys 已指定，上面的檢查已經過濾了不需要的表。
        // 但爲了兼容舊模式邏輯（未指定 targetSheetKeys 時），仍保留 mode 檢查。
        // 如果 targetSheetKeys 存在，我們假設調用者知道自己在做什麼，shouldShowData 默認爲 true。

        const isSummaryTable = isSummaryOrOutlineTable_ACU(table.name);
        let shouldShowData = true;

        if (!targetSheetKeys) {
            // [邏輯優化] 使用更明確的模式匹配
            const isUnifiedMode = (updateMode === 'full' || updateMode === 'manual_unified' || updateMode === 'auto_unified');
            const isStandardMode = (updateMode === 'standard' || updateMode === 'auto_standard' || updateMode === 'manual_standard');
            const isSummaryMode = (updateMode === 'summary' || updateMode === 'auto_summary_silent' || updateMode === 'manual_summary');

            if (isUnifiedMode) {
                 // 統一更新模式：顯示所有表
                 shouldShowData = true;
            } else if (isStandardMode && isSummaryTable) {
                // 標準表更新模式：不顯示總結表數據
                shouldShowData = false;
            } else if (isSummaryMode && !isSummaryTable) {
                // 總結表更新模式：不顯示標準表數據
                shouldShowData = false;
            }
        }

        if (!shouldShowData) {
            return;
        }

        const allRows = table.content.slice(1);
        // seedRows 統一從“當前數據/指導表/模板”解析（避免 seedRows 丟失導致誤判爲空表）
        const seedRows = getEffectiveSeedRowsForSheet_ACU(sheetKey, { guideData: _seedGuideDataForThisPrepare_ACU, allowTemplateFallback: true });
        // 把 seedRows 字段掛回 table，便於後續 applyEdits 物化
        try {
            if ((!Array.isArray(table.seedRows) || table.seedRows.length === 0) && Array.isArray(seedRows) && seedRows.length > 0) {
                table.seedRows = JSON.parse(JSON.stringify(seedRows));
            }
        } catch (e) {}
        const isUsingSeedRows = (allRows.length === 0 && seedRows.length > 0);
        if (isUsingSeedRows) {
            try { _seedRowsTablesUsed_ACU.push(String(table.name || sheetKey)); } catch (e) {}
        }
        const effectiveAllRows = (allRows.length > 0) ? allRows : (seedRows.length > 0 ? seedRows : []);

        // [新增] 當表格數據爲空時，簡化輸出並提示初始化
        if (effectiveAllRows.length === 0) {
            tableDataText += `[${tableIndex}:${table.name}]\n`;

            // [修正] 即使表格爲空，也必須輸出表頭列名，以便AI知道如何初始化（列結構）
            const headers = table.content[0] ? table.content[0].slice(1).map((h, i) => `[${i}:${h}]`).join(', ') : 'No Headers';
            tableDataText += `  Columns: ${headers}\n`;

            if (table.sourceData) {
                tableDataText += `  - Note: ${table.sourceData.note || 'N/A'}\n`;
                // 只發送 "initNode" 裏的內容 (如果沒有 initNode 則嘗試使用 insertNode)
                const initNodeContent = table.sourceData.initNode || table.sourceData.insertNode || 'N/A';
                tableDataText += `  - Init Trigger: ${initNodeContent}\n`;
            }
            tableDataText += `  (該表格爲空，請進行初始化。)\n\n`;
        } else {
            tableDataText += `[${tableIndex}:${table.name}]\n`;
            const headers = table.content[0] ? table.content[0].slice(1).map((h, i) => `[${i}:${h}]`).join(', ') : 'No Headers';
            tableDataText += `  Columns: ${headers}\n`;
            if (table.sourceData) {
                tableDataText += `  - Note: ${table.sourceData.note || 'N/A'}\n`;
                tableDataText += `  - Insert Trigger: ${table.sourceData.insertNode || table.sourceData.initNode || 'N/A'}\n`;
                tableDataText += `  - Update Trigger: ${table.sourceData.updateNode || 'N/A'}\n`;
                tableDataText += `  - Delete Trigger: ${table.sourceData.deleteNode || 'N/A'}\n`;
            }
            if (isUsingSeedRows) {
                tableDataText += `  - SeedRows: 已提供模板基礎數據（尚未寫入聊天樓層數據；本次填表可直接基於這些行更新）\n`;
            }

            let rowsToProcess = effectiveAllRows;
            let startIndex = 0;

            // [健全機制] 紀要表/總結表：固定使用硬編碼的10條限制，不受 sendLatestRows 參數影響
            // 這是爲了保證紀要表的行爲一致性，避免用戶誤配置導致發送過多數據
            const isSummaryTable = (table.name.trim() === '紀要表' || table.name.trim() === '總結表');
            if (isSummaryTable && effectiveAllRows.length > 10) {
                startIndex = effectiveAllRows.length - 10;
                rowsToProcess = effectiveAllRows.slice(-10);
                tableDataText += `  - Note: Showing last ${rowsToProcess.length} of ${effectiveAllRows.length} entries (summary table fixed limit).\n`;
            } else if (!isSummaryTable) {
                // [新增] 其他表：使用 sendLatestRows 參數控制發送行數
                // -1 = 全部發送，0 = 全部發送（沿用UI全局），正數 = 僅發送最新N條
                const sendLatestRows = (table.updateConfig && typeof table.updateConfig.sendLatestRows === 'number')
                    ? table.updateConfig.sendLatestRows : -1;
                if (sendLatestRows > 0 && effectiveAllRows.length > sendLatestRows) {
                    startIndex = effectiveAllRows.length - sendLatestRows;
                    rowsToProcess = effectiveAllRows.slice(-sendLatestRows);
                    tableDataText += `  - Note: Showing last ${rowsToProcess.length} of ${effectiveAllRows.length} entries (sendLatestRows=${sendLatestRows}).\n`;
                }
            }

            if (rowsToProcess.length > 0) {
                rowsToProcess.forEach((row, index) => {
                    const originalRowIndex = startIndex + index; // 計算原始行索引
                    const rowData = row.slice(1).join(', ');
                    tableDataText += `  [${originalRowIndex}] ${rowData}\n`;
                });
            } else {
                tableDataText += '  (No data rows)\n';
            }
            tableDataText += '\n';
        }
    });
    if (_seedRowsTablesUsed_ACU.length > 0) {
        logDebug_ACU(`[SeedRows] $0 使用 seedRows 作爲基礎數據：${_seedRowsTablesUsed_ACU.join('、')}`);
    }

    // 2. Format the messages for $1
    let messagesText = '當前最新對話內容:\n';
    if (messages && messages.length > 0) {
        // [上下文篩選] 正文標籤提取 + 標籤排除（可單獨或疊加）
        const extractTags = (settings_ACU.tableContextExtractTags || '').trim();
        const extractRules = normalizeExtractRules_ACU(settings_ACU.tableContextExtractRules, extractTags);
        const excludeTags = (settings_ACU.tableContextExcludeTags || '').trim();
        const excludeRules = normalizeExcludeRules_ACU(settings_ACU.tableContextExcludeRules, excludeTags);

        messagesText += messages.map(msg => {
            const prefix = msg.is_user ? SillyTavern_API_ACU?.name1 || '用戶' : msg.name || '角色';
            let content = msg.mes || msg.message || '';

            // 對非用戶消息應用上下文篩選（User回覆不受影響）
            if (!msg.is_user && (extractTags || extractRules.length > 0 || excludeTags || excludeRules.length > 0)) {
                content = applyContextTagFilters_ACU(content, { extractTags, extractRules, excludeTags, excludeRules });
            }

            return `${prefix}: ${content}`;
        }).join('\n');
    } else {
        messagesText += '(無最新對話內容)';
    }

    // [改動] 世界書初始掃描文本使用“本次實際讀取的上下文”（與劇情推進一致）
    // 用 messagesText（已應用上下文標籤提取/排除規則）作爲掃描源，避免誤用全聊天記錄導致觸發漂移
    const worldbookScanText = messagesText;
    const excludeImportTaggedWorldbookEntries = options?.excludeImportTaggedWorldbookEntries === true;
    const worldbookContent = await getCombinedWorldbookContent_ACU(worldbookScanText, {
        excludeImportTaggedEntries: excludeImportTaggedWorldbookEntries,
    });
    const manualExtraHintText = manualExtraHint_ACU || '';

    // Return the dynamic parts for interpolation.
    return { tableDataText, messagesText, worldbookContent, manualExtraHint: manualExtraHintText };
}

async function callCustomOpenAI_ACU(dynamicContent, abortController = null, options = null) {
    // [新增] 創建一個新的 AbortController 用於本次請求
    const localAbortController = abortController || new AbortController();
    currentAbortController_ACU = localAbortController;
    trackAbortController_ACU(localAbortController);
    const abortSignal = localAbortController.signal;
    const skipProfileSwitch = !!options?.skipProfileSwitch;
    const forceDirectApi = !!options?.forceDirectApi;

    // [新增] 獲取填表使用的API配置（支持API預設）
    const apiPresetConfig = getApiConfigByPreset_ACU(settings_ACU.tableApiPreset);
    const effectiveApiMode = apiPresetConfig.apiMode;
    const effectiveApiConfig = apiPresetConfig.apiConfig;
    const effectiveTavernProfile = apiPresetConfig.tavernProfile;

    // 僅用於發給API時的角色歸一化（不做A/B強制）
    const normalizeRoleForApi_ACU = (role) => {
        const ru = String(role || '').toUpperCase();
        const rl = String(role || '').toLowerCase();
        if (ru === 'AI' || ru === 'ASSISTANT' || rl === 'assistant') return 'assistant';
        if (ru === 'SYSTEM' || rl === 'system') return 'system';
        if (ru === 'USER' || rl === 'user') return 'user';
        return 'user';
    };

    // This function now assembles the final messages array.
    const messages = [];
    const charCardPromptSetting = settings_ACU.charCardPrompt;

    let promptSegments = [];
    if (Array.isArray(charCardPromptSetting)) {
        promptSegments = charCardPromptSetting;
    } else if (typeof charCardPromptSetting === 'string') {
        // Handle legacy single-string format
        promptSegments = [{ role: 'USER', content: charCardPromptSetting }];
    }

    // [新增] 構建 $U (用戶設定描述) 和 $C (角色描述) 佔位符內容
    // $U: 用戶設定描述 (persona_description)
    let userInfoContent_Table = '';
    try {
