        margin-bottom: 8px;
    }

    /* ═══ 主內容區 ═══ */
    .acu-vis-main {
        flex: 1;
        background: var(--vis-bg-color);
        background-image:
          url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.04'/%3E%3C/svg%3E");
        color: var(--vis-text-main);
        overflow-y: auto;
        padding: 24px;
    }

    /* ═══ 表格導航項 ═══ */
    .acu-table-nav-item {
        padding: 10px 12px;
        cursor: pointer;
        border-radius: 2px;
        color: var(--vis-text-dim);
        transition: all 0.2s ease;
        display: flex;
        align-items: center;
        justify-content: flex-start;
        width: 100%; /* 確保導航項佔滿側邊欄寬度 */
        box-sizing: border-box;
        position: relative;
        padding-left: 20px;
    }

    /* 古典豎線裝飾 */
    .acu-table-nav-item::before {
        content: '';
        position: absolute;
        left: 8px;
        top: 50%;
        transform: translateY(-50%);
        width: 1px;
        height: 60%;
        background-color: var(--vis-border-color);
        transition: background-color 0.2s ease;
    }

    .acu-table-nav-item:hover {
        background: var(--vis-bg-hover);
        color: var(--vis-text-main);
    }

    .acu-table-nav-item:hover::before {
        background-color: var(--vis-accent);
    }

    .acu-table-nav-item.active {
        background: rgba(123, 183, 255, 0.10);
        color: var(--vis-accent);
    }

    .acu-table-nav-item.active::before {
        background-color: var(--vis-accent);
    }

    .acu-table-nav-item i { width: 20px; text-align: center; color: var(--vis-text-mute); }
    .acu-table-nav-item.active i { color: var(--vis-accent); }

    .acu-table-nav-content {
        display: flex;
        align-items: center;
        gap: 8px;
        flex: 1 1 0; /* 使用 flex-basis: 0 確保能正確伸展填滿 */
        min-width: 0; /* 允許 flex 子項收縮 */
        width: 0; /* 配合 flex: 1 確保能正確計算寬度 */
    }

    .acu-table-index {
        flex-shrink: 0;
        min-width: 28px;
        text-align: center;
        font-size: 11px;
        opacity: 0.5;
        font-family: var(--vis-font-serif);
        letter-spacing: 1px;
    }

    .acu-table-name {
        /* 表格名稱：優先完整顯示，超長時省略 */
        flex: 1 1 0; /* 使用 flex-basis: 0 確保正確伸展 */
        min-width: 0;
        width: 0; /* 配合 flex 確保能正確計算寬度並省略 */
        overflow: hidden;
        text-overflow: ellipsis;
        white-space: nowrap;
        line-height: 1.4;
    }

    .acu-table-nav-actions {
        display: flex;
        gap: 2px;
        opacity: 0;
        transition: opacity 0.15s;
        flex-shrink: 0; /* 防止按鈕被壓縮 */
        margin-left: auto; /* 使用 auto margin 將按鈕推到最右邊 */
        padding-left: 6px; /* 與內容保持間距 */
    }

    .acu-table-nav-item:hover .acu-table-nav-actions {
        opacity: 1;
    }

    .acu-table-nav-item.active .acu-table-nav-actions {
        opacity: 0.7; /* 選中項也顯示操作按鈕 */
    }

    .acu-table-order-btn {
        background: transparent;
        border: 1px solid var(--vis-border-color);
        color: var(--vis-text-mute);
        width: 22px;
        height: 22px;
        border-radius: 1px;
        cursor: pointer;
        display: flex;
        align-items: center;
        justify-content: center;
        transition: all 0.15s;
        font-size: 10px;
    }

    .acu-table-order-btn:hover {
        background: rgba(123, 183, 255, 0.12);
        border-color: var(--vis-accent);
        color: var(--vis-accent);
    }

    .acu-table-order-btn:disabled {
        opacity: 0.25;
        cursor: not-allowed;
    }

    /* ═══ 按鈕 ═══ */
    .acu-btn-primary {
        background: rgba(123, 183, 255, 0.12);
        color: var(--vis-accent);
        border: 1px solid var(--vis-accent);
        padding: 10px 20px;
        border-radius: 1px;
        cursor: pointer;
        font-family: var(--vis-font-serif);
        font-size: 12px;
        letter-spacing: 1px;
        transition: all 0.2s ease;
    }
    .acu-btn-primary:hover {
        background: rgba(123, 183, 255, 0.18);
        box-shadow: 0 0 0 2px var(--vis-accent-glow);
    }

    /* 小按鈕樣式優化 */
    #acu-visualizer-content .acu-btn-small {
        padding: 6px 12px;
        font-size: 11px;
        min-width: auto;
        height: 32px;
        letter-spacing: 1px;
    }

    .acu-btn-secondary {
        background: transparent;
        color: var(--vis-text-dim);
        border: 1px solid var(--vis-border-color);
        padding: 10px 20px;
        border-radius: 1px;
        cursor: pointer;
        font-family: var(--vis-font-serif);
        font-size: 12px;
        letter-spacing: 1px;
        transition: all 0.2s ease;
    }
    .acu-btn-secondary:hover {
        color: var(--vis-text-main);
        border-color: var(--vis-text-mute);
        background: var(--vis-bg-hover);
    }

    /* ═══ 數據卡片 ═══ */
    .acu-card-grid {
        display: flex;
        flex-wrap: wrap;
        gap: 16px;
        align-content: flex-start;
    }

    .acu-data-card {
        background: var(--vis-bg-light);
        border-radius: 2px;
        box-shadow: none;
        width: 300px;
        display: flex;
        flex-direction: column;
        overflow: hidden;
        border: 1px solid var(--vis-border-color);
        transition: border-color 0.2s ease;
    }

    .acu-data-card:hover {
        border-color: var(--vis-accent);
    }

    .acu-card-header {
        padding: 12px 16px;
        background: var(--vis-bg-stats);
        border-bottom: 1px solid var(--vis-border-color);
        font-weight: normal;
        font-size: 13px;
        display: flex;
        justify-content: space-between;
        align-items: center;
        color: var(--vis-text-main);
        letter-spacing: 1px;
    }

    .acu-card-body {
        padding: 14px 16px;
        font-size: 13px;
        display: flex;
        flex-direction: column;
        gap: 10px;
        line-height: 1.8;
        color: var(--vis-text-dim);
    }

    .acu-field-row { display: flex; flex-direction: column; gap: 4px; }

    .acu-field-label {
        font-size: 10px;
        color: var(--vis-text-mute);
        font-weight: normal;
        letter-spacing: 1px;
    }

    .acu-field-value {
        padding: 8px 10px;
        border: 1px solid transparent;
        border-radius: 1px;
        min-height: 20px;
        word-break: break-word;
        white-space: pre-wrap;
        background: var(--vis-bg-color);
        transition: all 0.15s ease;
    }
    .acu-field-value:hover {
        background: var(--vis-bg-hover);
        border-color: var(--vis-border-color);
        cursor: text;
    }
    .acu-field-value:focus {
        background: var(--vis-bg-color);
        border-color: var(--vis-accent);
        outline: none;
        box-shadow: 0 0 0 2px var(--vis-accent-glow);
    }

    /* ═══ 配置面板 ═══ */
    .acu-config-panel {
        background: var(--vis-bg-light);
        padding: 24px;
        border-radius: 2px;
        box-shadow: none;
        max-width: 800px;
        margin: 0 auto;
        border: 1px solid var(--vis-border-color);
    }

    .acu-config-section {
        margin-bottom: 24px;
        padding-bottom: 24px;
        border-bottom: 1px solid var(--vis-border-color);
    }

    .acu-config-section:last-child {
        border-bottom: none;
        margin-bottom: 0;
        padding-bottom: 0;
    }

    .acu-config-section h4 {
        margin: 0 0 16px 0;
        color: var(--vis-text-main);
        font-family: var(--vis-font-serif);
        font-size: 14px;
        font-weight: normal;
        letter-spacing: 2px;
    }

    .acu-form-group { margin-bottom: 16px; }

    .acu-form-group label {
        display: block;
        margin-bottom: 6px;
        font-weight: normal;
        color: var(--vis-text-dim);
        font-size: 12px;
        letter-spacing: 1px;
    }

    .acu-form-input {
        width: 100%;
        padding: 10px 12px;
        border: 1px solid var(--vis-border-color);
        border-radius: 1px;
        box-sizing: border-box;
        font-family: var(--vis-font-serif);
        font-size: 14px;
        background: var(--vis-bg-color);
        color: var(--vis-text-main);
        transition: border-color 0.15s, box-shadow 0.15s;
    }

    .acu-form-input:focus {
        outline: none;
        border-color: var(--vis-accent);
        box-shadow: 0 0 0 2px var(--vis-accent-glow);
    }

    .acu-form-textarea {
        width: 100%;
        padding: 10px 12px;
        border: 1px solid var(--vis-border-color);
        border-radius: 1px;
        box-sizing: border-box;
        min-height: 100px;
        resize: vertical;
        font-family: var(--vis-font-serif);
        font-size: 14px;
        background: var(--vis-bg-color);
        color: var(--vis-text-main);
        line-height: 1.8;
    }

    .acu-form-textarea:focus {
        outline: none;
        border-color: var(--vis-accent);
        box-shadow: 0 0 0 2px var(--vis-accent-glow);
    }

    .acu-hint {
        font-size: 11px;
        color: var(--vis-text-mute);
        margin-top: 4px;
        letter-spacing: 0.5px;
    }

    /* ═══ 模式切換 ═══ */
    .acu-mode-switch {
        display: flex;
        background: var(--vis-bg-stats);
        border-radius: 2px;
        padding: 3px;
        margin-right: 12px;
        border: 1px solid var(--vis-border-color);
    }

    .acu-mode-btn {
        padding: 6px 16px;
        border-radius: 1px;
        cursor: pointer;
        color: var(--vis-text-mute);
        font-size: 12px;
        font-family: var(--vis-font-serif);
        border: none;
        background: transparent;
        transition: all 0.2s ease;
        letter-spacing: 1px;
    }
    .acu-mode-btn:hover {
        color: var(--vis-text-main);
        background: var(--vis-bg-hover);
    }
    .acu-mode-btn.active {
        background: rgba(123, 183, 255, 0.12);
        color: var(--vis-accent);
    }

    /* ═══ 列編輯器 ═══ */
    .acu-col-list { display: flex; flex-direction: column; gap: 6px; }

    /* ═══ 表格鎖定（僅 updateRow 生效） ═══ */
    .acu-lock-btn {
        border: 1px solid var(--vis-border-color);
        background: transparent;
        color: var(--vis-text-mute);
        border-radius: 1px;
        padding: 2px 6px;
        font-size: 11px;
        cursor: pointer;
        display: inline-flex;
        align-items: center;
        gap: 4px;
        transition: all 0.15s ease;
        font-family: var(--vis-font-serif);
    }
    .acu-lock-btn:hover {
        border-color: var(--vis-accent);
        color: var(--vis-accent);
    }
    .acu-lock-btn.active {
        border-color: var(--vis-accent);
        background: rgba(123, 183, 255, 0.12);
        color: var(--vis-accent);
    }
    .acu-lock-btn.special {
        border-color: var(--vis-accent);
        background: rgba(123, 183, 255, 0.08);
        color: var(--vis-accent-dim);
    }
    .acu-field-value-wrap { display: flex; align-items: center; gap: 6px; }
    .acu-field-value { flex: 1; min-width: 0; }
    .acu-field-row.acu-locked-field .acu-field-value {
        background: rgba(123, 183, 255, 0.06);
        border-color: rgba(123, 183, 255, 0.20);
        opacity: 0.85;
    }

    .acu-col-item {
        display: flex;
        gap: 8px;
        align-items: center;
        background: var(--vis-bg-stats);
        padding: 8px 10px;
        border-radius: 1px;
        border: 1px solid var(--vis-border-color);
    }

    .acu-col-input {
        flex: 1;
        padding: 8px 10px;
        border: 1px solid var(--vis-border-color);
        border-radius: 1px;
        font-family: var(--vis-font-serif);
        background: var(--vis-bg-color);
        font-size: 13px;
        color: var(--vis-text-main);
        transition: border-color 0.15s ease;
    }

    .acu-col-input:focus {
        outline: none;
        border-color: var(--vis-accent);
        box-shadow: 0 0 0 2px var(--vis-accent-glow);
    }

    .acu-col-btn {
        padding: 6px 10px;
        cursor: pointer;
        border: 1px solid var(--vis-border-color);
        border-radius: 1px;
        background: transparent;
        color: var(--vis-text-mute);
        transition: all 0.15s ease;
        font-size: 11px;
        font-family: var(--vis-font-serif);
    }

    .acu-col-btn:hover {
        background: rgba(123, 183, 255, 0.12);
        border-color: var(--vis-accent);
        color: var(--vis-accent);
    }

    /* ═══ 滾動條 ═══ */
    .acu-vis-sidebar::-webkit-scrollbar,
    .acu-vis-main::-webkit-scrollbar {
        width: 4px;
    }

    .acu-vis-sidebar::-webkit-scrollbar-track,
    .acu-vis-main::-webkit-scrollbar-track {
        background: transparent;
    }

    .acu-vis-sidebar::-webkit-scrollbar-thumb,
    .acu-vis-main::-webkit-scrollbar-thumb {
        background: var(--vis-border-color);
        border-radius: 1px;
    }

    .acu-vis-sidebar::-webkit-scrollbar-thumb:hover,
    .acu-vis-main::-webkit-scrollbar-thumb:hover {
        background: var(--vis-text-mute);
    }

    /* ═══ 新增表格按鈕 ═══ */
    .acu-add-table-btn {
        padding: 10px 12px;
        cursor: pointer;
        border-radius: 1px;
        color: var(--vis-text-mute);
        background: transparent;
        border: 1px dashed var(--vis-border-color);
        display: flex;
        align-items: center;
        justify-content: center;
        gap: 6px;
        transition: all 0.2s ease;
        font-family: var(--vis-font-serif);
        font-size: 12px;
        margin-top: 8px;
        letter-spacing: 1px;
    }

    .acu-add-table-btn:hover {
        background: var(--vis-bg-hover);
        border-color: var(--vis-accent);
        border-style: solid;
        color: var(--vis-accent);
    }

    /* ═══ 刪除表格按鈕 ═══ */
    .acu-vis-del-table-btn {
        background: transparent;
        border: none;
        color: var(--vis-text-mute);
        opacity: 0.5;
        cursor: pointer;
        padding: 4px;
        transition: all 0.15s ease;
        font-size: 12px;
    }

    .acu-vis-del-table-btn:hover {
        opacity: 1;
        color: var(--vis-accent);
    }

    /* ═══════════════════════════════════════════════════════════════
       響應式佈局 - 可視化編輯器
       ═══════════════════════════════════════════════════════════════ */

    /* 寬屏優化 (≥1400px) - 適度增大側邊欄顯示更完整的表格名 */
    @media screen and (min-width: 1400px) {
        .acu-vis-sidebar {
            flex: 0 0 320px; /* 從380px拉窄到320px，避免佔用過多空間 */
            max-width: 380px;
        }

        .acu-table-nav-item {
            padding: 10px 12px;
            width: 100%; /* 確保佔滿側邊欄寬度 */
        }

        .acu-table-name {
            /* 寬屏時允許表格名換行顯示 */
            white-space: normal;
            word-break: break-word;
            flex: 1 1 0;
            width: 0;
        }
    }

    /* 超寬屏 (≥1800px) */
    @media screen and (min-width: 1800px) {
        .acu-vis-sidebar {
            flex: 0 0 360px; /* 從420px拉窄到360px */
            max-width: 420px;
        }

        .acu-table-name {
            font-size: 14px;
        }
    }

    /* 平板及以下 (≤768px) */
    @media screen and (max-width: 768px) {
        #acu-visualizer-content {
            font-size: 13px;
        }

        /* 頂部欄 */
        .acu-vis-header {
            flex: 0 0 auto;
            min-height: 50px;
            padding: 10px 16px;
            flex-wrap: wrap;
            gap: 10px;
        }

        .acu-vis-title {
            font-size: 14px;
            letter-spacing: 2px;
            width: 100%;
            text-align: center;
            order: 1;
        }

        .acu-mode-switch {
            order: 2;
            margin-right: 0;
        }

        .acu-vis-actions {
            order: 3;
            width: 100%;
            justify-content: center;
        }

        /* 內容區域 - 垂直佈局 */
        .acu-vis-content {
            flex-direction: column;
        }

        /* 側邊欄變爲頂部橫向滾動 */
        .acu-vis-sidebar {
            flex: 0 0 auto;
            width: 100%;
            /* 關鍵修復：基礎樣式裏存在 max-width:400px/min-width:280px，
               在移動端會把“頂部橫條”寬度卡死，導致右側出現空白背景區域 */
            max-width: none !important;
            min-width: 0 !important;
            box-sizing: border-box;
            max-height: 120px;
            border-right: none;
            border-bottom: 1px solid var(--vis-border-color);
            flex-direction: row;
            flex-wrap: nowrap;
            overflow-x: auto;
            overflow-y: hidden;
            gap: 8px;
            padding: 12px;
            -webkit-overflow-scrolling: touch;
            /* 關鍵：避免被外部樣式“拉開間距”導致中間/右側出現大塊空白 */
            justify-content: flex-start !important;
            align-items: stretch;
        }

        .acu-vis-sidebar::before {
            display: none;
        }

        .acu-vis-sidebar::-webkit-scrollbar {
            height: 4px;
            width: auto;
        }

        /* 表格導航項 - 橫向佈局 */
        .acu-table-nav-item {
            /* 顯式禁用 grow/shrink，保證按內容緊湊排列；超出則橫向滾動 */
            flex: 0 0 auto;
            padding: 8px 12px;
            width: auto; /* 橫向滾動時寬度由內容決定 */
            min-width: fit-content; /* 確保最小寬度包裹內容 */
            display: inline-flex;
        }

        .acu-table-nav-content {
            gap: 6px;
            flex: 0 0 auto; /* 橫向滾動時不伸縮，保持內容寬度 */
            width: auto; /* 重置寬度 */
        }

        .acu-table-name {
            white-space: nowrap; /* 確保表格名不換行 */
            overflow: visible; /* 窄屏下不截斷，完整顯示 */
            text-overflow: clip;
            flex: 0 0 auto; /* 不伸縮，寬度由內容決定 */
            width: auto; /* 重置寬度 */
        }

        .acu-table-index {
            display: none; /* 隱藏序號 */
        }

        .acu-table-nav-actions {
            opacity: 1;
            gap: 2px;
            flex: 0 0 auto; /* 不允許伸縮 */
            /* 強制取消全局的 margin-left:auto（否則會把按鈕推到最右，產生巨量空白） */
            margin-left: 6px !important;
            padding-left: 0;
        }

        .acu-table-order-btn {
            width: 20px;
            height: 20px;
            font-size: 9px;
        }

        /* 新增表格按鈕 */
        .acu-add-table-btn {
            flex-shrink: 0;
            padding: 8px 12px;
            margin-top: 0;
        }

        /* 主內容區 */
        .acu-vis-main {
            padding: 16px;
        }

        /* 數據卡片 */
        .acu-card-grid {
            gap: 12px;
        }

        .acu-data-card {
            width: 100%;
            min-width: 0;
        }

        .acu-card-header {
            padding: 10px 12px;
            font-size: 13px;
        }

        .acu-card-body {
            padding: 10px 12px;
            font-size: 12px;
        }

        /* 配置面板 */
        .acu-config-panel {
            padding: 16px;
        }

        .acu-config-section {
            margin-bottom: 16px;
            padding-bottom: 16px;
        }

        .acu-config-section h4 {
            font-size: 14px;
        }

        .acu-form-group {
            margin-bottom: 12px;
        }

        .acu-form-input,
        .acu-form-textarea {
            font-size: 14px; /* 防止iOS縮放 */
            padding: 10px;
        }

        /* 列編輯器 */
        .acu-col-item {
            flex-wrap: wrap;
            gap: 6px;
        }

        .acu-col-input {
            width: 100%;
            flex: none;
        }

        /* 按鈕 */
        .acu-btn-primary,
        .acu-btn-secondary {
            padding: 10px 16px;
            font-size: 12px;
        }
    }

    /* 手機 (≤480px) */
    @media screen and (max-width: 480px) {
        #acu-visualizer-content {
            font-size: 12px;
        }

        .acu-vis-header {
            padding: 8px 12px;
        }

        .acu-vis-title {
            font-size: 13px;
            letter-spacing: 1px;
        }

        .acu-vis-title i {
            display: none;
        }

        .acu-mode-switch {
            padding: 2px;
        }

        .acu-mode-btn {
            padding: 5px 10px;
            font-size: 11px;
        }

        .acu-btn-primary,
        .acu-btn-secondary {
